(window.CLAVE_TEST=window.CLAVE_TEST||{})[3]=[{"a":"Artículo 1 — Creación de la Unión Europea","q":[{"i":"3-ia-3004","p":"Tratado de la Unión Europea. Creación de la Unión Europea. Por el presente Tratado, las ALTAS PARTES CONTRATANTES constituyen entre sí una UNIÓN EUROPEA, a la que los Estados miembros atribuyen competencias para:","o":["garantizar su soberanía compartida.","alcanzar sus objetivos comunes.","ejercer conjuntamente el poder legislativo.","desarrollar una política exterior propia."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">alcanzar sus objetivos comunes</mark></span>El <span class=\"ref-norma\">art. 1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a la que los Estados miembros atribuyen competencias para alcanzar sus\"</span>. La atribución de competencias es para alcanzar sus objetivos comunes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-75","p":"Tratado de la Unión Europea. El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más ___________ a los ciudadanos que sea posible.","o":["Abierta y próxima.","Democrática y cercana.","Participativa y cercana.","Transparente y próxima."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Abierta y próxima</mark></span>El <span class=\"ref-norma\">art. 1 del TUE</span> dispone: <span class=\"ref-concepto\">\"El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible\"</span>. El artículo 1 del TUE dispone que el Tratado constituye una nueva etapa en el proceso de unión, \"en la cual las decisiones serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible\"."},{"i":"3-98","p":"Tratado de la Unión Europea. El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más __________ a los ciudadanos que sea posible.","o":["Transparente y próxima.","Abierta y próxima.","Transparente y abierta.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Abierta y próxima</mark></span>El <span class=\"ref-norma\">art. 1 del TUE</span> dispone: <span class=\"ref-concepto\">\"El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible\"</span>. El artículo 1 del TUE señala que el Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible."},{"i":"3-217","p":"Tratado de la Unión Europea. ¿Cómo serán tomadas las decisiones en la Unión Europea?","o":["De la forma más abierta y próxima a los ciudadanos que sea posible.","De la forma más reservada y próxima a los ciudadanos que sea posible.","De la forma más subjetiva y próxima a los ciudadanos que sea posible.","De la forma más subjetiva, abierta y próxima a los ciudadanos que sea posible."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">De la forma más abierta y próxima a los ciudadanos que sea posible</mark></span>El <span class=\"ref-norma\">art. 10.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Todo ciudadano tiene derecho a participar en la vida democrática de la Unión. Las decisiones serán tomadas de la forma más abierta y próxima posible a los ciudadanos\"</span>. El artículo 1 del TUE establece que las decisiones de la Unión serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible."},{"i":"3-314","p":"Tratado de la Unión Europea. El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más ___________ a los ciudadanos que sea posible.","o":["Abierta y próxima.","Democrática y cercana.","Participativa y cercana.","Transparente y próxima."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Abierta y próxima</mark></span>El <span class=\"ref-norma\">art. 1 del TUE</span> dispone: <span class=\"ref-concepto\">\"El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible\"</span>. El artículo 1 TUE recoge literalmente que las decisiones serán tomadas de la forma más abierta y próxima a los ciudadanos que sea posible."},{"i":"3-ia-3005","p":"Tratado de la Unión Europea. Creación de la Unión Europea. El presente Tratado constituye una nueva etapa en el proceso creador de una unión cada vez más estrecha entre los pueblos de Europa, en la cual las decisiones serán tomadas:","o":["de la forma más abierta y próxima a los ciudadanos que sea posible.","de la forma más eficaz y coordinada entre las instituciones que sea posible.","de la forma más transparente y participativa entre los Estados que sea posible.","de la forma más ágil y simplificada para los ciudadanos que sea posible."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de la forma más abierta y próxima a los ciudadanos que sea posible</mark></span>El <span class=\"ref-norma\">art. 1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"las decisiones serán tomadas de la forma más abierta y próxima a los\"</span>. La fórmula es «de la forma más abierta y próxima a los ciudadanos que sea posible». <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-239","p":"Tratado de la Unión Europea. ¿Qué Tratado tiene más valor jurídico, el Tratado de la Unión Europea o el Tratado de Funcionamiento de la Unión Europea?","o":["Ambos tienen el mismo valor jurídico.","El Tratado de Funcionamiento de la Unión Europea.","El Tratado de la Unión Europea.","Ninguno de los dos Tratados tiene valor jurídico."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Ambos tienen el mismo valor jurídico</mark></span>El <span class=\"ref-norma\">art. 1 del TUE</span> dispone: <span class=\"ref-concepto\">\"Ambos Tratados tienen el mismo valor jurídico\"</span>. El artículo 1 del TUE establece que la Unión se fundamenta en el TUE y en el TFUE, y que ambos Tratados tienen el mismo valor jurídico."},{"i":"3-100","p":"Tratado de Funcionamiento de la Unión Europea. ¿Qué organismo se encarga de apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros del terrorismo y de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos?","o":["Europol","Interpol.","Eurojust.","La Fiscalía Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Europol</mark></span>El <span class=\"ref-norma\">art. 88.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Europol es apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros, del terrorismo y de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos\"</span>. El artículo 88.1 del TFUE define la función de Europol como apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros en la prevención y lucha contra la delincuencia grave, el terrorismo y otras formas de delincuencia que afecten a un interés común de la Unión."},{"i":"3-206","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién tiene la función de apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros, del terrorismo y de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos?","o":["Eurojust.","Europol.","El Tribunal de Justicia de la Unión Europea.","Interpol."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Europol</mark></span>El <span class=\"ref-norma\">art. 88.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Europol es apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros, del terrorismo y de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos\"</span>. El artículo 88.1 del TFUE define la función de Europol como apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros en la prevención y lucha contra la delincuencia grave, el terrorismo y otras formas de delincuencia de interés común para la Unión."},{"i":"3-321","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién tiene la función de apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros, del terrorismo y de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos?","o":["Eurojust.","Europol.","El Tribunal de Justicia de la Unión Europea.","Interpol."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Europol</mark></span>El <span class=\"ref-norma\">art. 88.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La función de Europol es apoyar y reforzar la actuación de las autoridades policiales y de los demás servicios con funciones coercitivas de los Estados miembros, así como su colaboración mutua en la prevención de la delincuencia grave que afecte a dos o más Estados miembros, del terrorismo y de las formas de delincuencia que lesionen un interés común que sea objeto de una política de la Unión, así como en la lucha en contra de ellos\"</span>. El artículo 88.1 TFUE atribuye esta función a Europol."},{"i":"3-ia-3006","p":"Tratado de la Unión Europea. Creación de la Unión Europea. La Unión se fundamenta en el presente Tratado y en el Tratado de Funcionamiento de la Unión Europea, que tienen el mismo valor jurídico; además, la Unión:","o":["sustituirá a la Comunidad Europea y a la Comunidad Europea de la Energía Atómica.","complementará a la Comunidad Europea y a su ordenamiento jurídico.","suprimirá la Comunidad Europea y heredará únicamente sus competencias.","sustituirá y sucederá a la Comunidad Europea."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">sustituirá y sucederá a la Comunidad Europea</mark></span>El <span class=\"ref-norma\">art. 1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La Unión sustituirá\"</span>. La Unión sustituye y sucede a la Comunidad Europea. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 2 — Valores en que se fundamenta la Unión R1 R2","q":[{"i":"3-24","p":"Tratado de la Unión Europea. El Tratado de la Unión Europea se fundamenta en los valores de:","o":["La libertad, la dignidad humana, la democracia, la igualdad, el Estado de Derecho y el respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.","La libertad, la democracia, la igualdad, el Estado de Derecho y el respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.","El respeto de la dignidad humana, la libertad, la democracia, la igualdad, el Estado de Derecho y el respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.","La libertad, la dignidad humana, la democracia, la igualdad, el Estado de Derecho, el respeto de los derechos humanos y la Paz."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El respeto de la dignidad humana, la libertad, la democracia, la igualdad, el Estado de Derecho y el respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías</mark></span>El <span class=\"ref-norma\">art. 2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. El artículo 2 del TUE establece que la Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías."},{"i":"3-107","p":"Tratado de la Unión Europea. Disposiciones comunes. Derechos y valores. La Unión se fundamenta en los valores que son respeto de:","o":["Dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos.","Dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.","Dignidad humana, libertad, democracia, igualdad, Estado social y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.","Dignidad humana, honra, democracia, igualdad, Estado social y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a mayorías."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías</mark></span>El <span class=\"ref-norma\">art. 2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. El artículo 2 del TUE establece que la Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías."},{"i":"3-213","p":"Tratado de la Unión Europea. Entre otros, la Unión se fundamenta en los valores de respeto de: señale la INCORRECTA.","o":["La parcialidad.","La igualdad.","El Estado de Derecho.","El respeto de los derechos humanos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La parcialidad</mark></span>El <span class=\"ref-norma\">art. 2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. La opción correcta es la A, por ser la incorrecta. El artículo 2 del TUE recoge entre los valores de la Unión la igualdad, el Estado de Derecho y el respeto de los derechos humanos, pero no la parcialidad, que resulta contraria al espíritu del propio precepto."},{"i":"3-228","p":"Tratado de la Unión Europea. La Unión se fundamenta en los valores de respeto de: señale la INCORRECTA.","o":["La proporcionalidad.","Igualdad.","Libertad.","Democracia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La proporcionalidad</mark></span>La proporcionalidad es un principio que rige el ejercicio de las competencias (art. 5), no un valor del art. 2. Según el <span class=\"ref-norma\">art. 2 del TUE</span>: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.\"</span> (verificado con el texto del temario)."},{"i":"3-328","p":"Tratado de la Unión Europea. Entre otros, la Unión se fundamenta en los valores de respeto de: señale la INCORRECTA.","o":["La parcialidad.","La igualdad.","El Estado de Derecho.","El respeto de los derechos humanos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La parcialidad</mark></span>El <span class=\"ref-norma\">art. 2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. El artículo 2 TUE cita la dignidad humana, la libertad, la democracia, la igualdad, el Estado de Derecho y el respeto de los derechos humanos; la parcialidad no forma parte de esta lista."},{"i":"3-ia-3007","p":"Tratado de la Unión Europea. Valores en que se fundamenta la Unión Europea. La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y:","o":["respeto de los derechos fundamentales, incluidos los derechos de las personas pertenecientes a minorías.","respeto de los derechos humanos y de las libertades fundamentales de todas las personas.","respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías.","solidaridad y protección de los derechos de las personas pertenecientes a minorías."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías</mark></span>El <span class=\"ref-norma\">art. 2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"igual-dad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. Seis valores, el último con mención a las minorías. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3408","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. La adopción de las normas mínimas sobre cooperación judicial en materia penal no impedirá que los Estados miembros mantengan o instauren:","o":["un nivel más estricto de persecución de las infracciones.","un nivel más elevado de protección de las personas.","un régimen más amplio de cooperación con terceros Estados.","un procedimiento penal alternativo para las infracciones transfronterizas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un nivel más elevado de protección de las personas</mark></span>El <span class=\"ref-norma\">art. 82.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"no impedirá que los Estados miembros mantengan o instauren un nivel más elevado de protección de las personas\"</span>. Los Estados pueden mantener o instaurar un nivel más elevado de protección de las personas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-90","p":"Tratado de la Unión Europea. La Unión se fundamenta en los valores de respeto de la dignidad humana, igualdad, entre otros. Estos valores son comunes a los Estados miembros en una sociedad caracterizada por el: Señala la incorrecta.","o":["El pluralismo.","La no discriminación.","La tolerancia.","La libertad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La libertad</mark></span>La libertad es un VALOR de la Unión, no un rasgo de la sociedad. Según el <span class=\"ref-norma\">art. 2 del TUE</span>: <span class=\"ref-concepto\">\"Estos valores son comunes a los Estados miembros en una sociedad caracterizada por el pluralismo, la no discriminación, la tolerancia, la justicia, la solidaridad y la igualdad entre mujeres y hombres.\"</span> (verificado con el texto del temario)."},{"i":"3-214","p":"Tratado de la Unión Europea. La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías. Estos valores son comunes a los Estados miembros en una sociedad caracterizada por: señale la INCORRECTA.","o":["El pluralismo.","La tolerancia.","La justicia.","La proporcionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La proporcionalidad</mark></span>El <span class=\"ref-norma\">art. 2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. (The list in the Treaty refers to pluralism, non-discrimination, tolerance, justice, solidarity, and equality between women and men, but not &quot;proporcionalidad&quot; (proportionality) as a characteristic of the society in which the values are common.)"},{"i":"3-329","p":"Tratado de la Unión Europea. La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías. Estos valores son comunes a los Estados miembros en una sociedad caracterizada por: señale la INCORRECTA.","o":["El pluralismo.","La tolerancia.","La justicia.","La proporcionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La proporcionalidad</mark></span>El <span class=\"ref-norma\">art. 2 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión se fundamenta en los valores de respeto de la dignidad humana, libertad, democracia, igualdad, Estado de Derecho y respeto de los derechos humanos, incluidos los derechos de las personas pertenecientes a minorías\"</span>. El artículo 2 TUE cita el pluralismo, la no discriminación, la tolerancia, la justicia, la solidaridad y la igualdad entre mujeres y hombres; la proporcionalidad no figura entre ellos."},{"i":"3-ia-3008","p":"Tratado de la Unión Europea. Valores en que se fundamenta la Unión Europea. Los valores de la Unión son comunes a los Estados miembros en una sociedad caracterizada por el pluralismo, la no discriminación, la tolerancia, la justicia, la solidaridad y:","o":["la igualdad de oportunidades y la cohesión social.","la igualdad entre mujeres y hombres.","la libertad de expresión y de religión.","la paz y la seguridad de sus ciudadanos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la igualdad entre mujeres y hombres</mark></span>El <span class=\"ref-norma\">art. 2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la tolerancia, la justicia, la solidaridad y la igualdad entre mujeres y hombres\"</span>. La sociedad común se caracteriza por pluralismo, no discriminación, tolerancia, justicia, solidaridad e igualdad entre mujeres y hombres. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 5 — Principios que delimitan las competencias R3 R4","q":[{"i":"3-48","p":"Tratado de la Unión Europea. ¿En virtud de qué principio la Unión actúa dentro de los límites de las competencias que le atribuyen los Estados miembros en los Tratados para lograr los objetivos que éstos determinan?","o":["Principio de subsidiariedad.","Principio de proporcionalidad.","Principio de atribución.","Las opciones A y C son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Principio de atribución</mark></span>El <span class=\"ref-norma\">art. 5.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007En virtud del principio de atribución, la Unión actúa dentro de los límites de las competencias que le atribuyen los Estados miembros en los Tratados para lograr los objetivos que éstos determinan. Toda competencia no atribuida a la Unión en los Tratados corresponde a los Estados miembros\"</span>. El artículo 5.2 del TUE define el principio de atribución como aquel en virtud del cual la Unión actúa dentro de los límites de las competencias que le atribuyen los Estados miembros en los Tratados para lograr los objetivos que éstos determinan."},{"i":"3-203","p":"Tratado de la Unión Europea. La delimitación de las competencias de la Unión se rige por el:","o":["Principio de atribución.","Principio de subsidiariedad.","Principio de proporcionalidad.","Principio de transparencia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Principio de atribución</mark></span>El <span class=\"ref-norma\">art. 5.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La delimitación de las competencias de la Unión se rige por el principio de atribución. El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad\"</span>. Terst 12 Based on the images provided, here is the complete list of questions and options from the test, ordered numerically from 1 to 20, along with the correct answers derived from the content on the Treaties of the European Union (EU) and the functioning of its institutions. Test on the Treaties of the European Union"},{"i":"3-268","p":"Tratado de la Unión Europea. ¿Por qué principio se rige la delimitación de las competencias de la Unión?","o":["Por el principio de subsidiariedad.","Por el principio de atribución.","Por el principio de proporcionalidad.","Por el principio de solidaridad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Por el principio de atribución</mark></span>El <span class=\"ref-norma\">art. 5.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La delimitación de las competencias de la Unión se rige por el principio de atribución. El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad\"</span>. El artículo 5.1 del TUE establece que la delimitación de las competencias de la Unión se rige por el principio de atribución."},{"i":"3-33","p":"Tratado de la Unión Europea. Principios que delimitan las competencias de la Unión Europea. Señala la opción correcta:","o":["La delimitación de las competencias de la Unión se rige por el principio de proporcionalidad.","El ejercicio de las competencias de la Unión se rige por los principios de atribución y proporcionalidad.","La delimitación de las competencias de la Unión se rige por el principio de subsidiariedad.","El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad</mark></span>El <span class=\"ref-norma\">art. 5.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La delimitación de las competencias de la Unión se rige por el principio de atribución. El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad\"</span>. El artículo 5.1 del TUE distingue que la delimitación de las competencias de la Unión se rige por el principio de atribución, mientras que el ejercicio de dichas competencias se rige por los principios de subsidiariedad y proporcionalidad."},{"i":"3-221","p":"Tratado de la Unión Europea. ¿Por qué principio se rige el ejercicio de las competencias de la Unión?","o":["Por los principios de atribución y solidaridad.","Por el principio de atribución.","Por los principios de subsidiariedad y proporcionalidad.","Por los principios de solidaridad y proporcionalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por los principios de subsidiariedad y proporcionalidad</mark></span>Atribución = DELIMITACIÓN; subsidiariedad y proporcionalidad = EJERCICIO. Según el <span class=\"ref-norma\">art. 5.1 del TUE</span>: <span class=\"ref-concepto\">\"La delimitación de las competencias de la Unión se rige por el principio de atribución. El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3022","p":"Tratado de la Unión Europea. Principios que delimitan las competencias. La delimitación de las competencias de la Unión se rige por el principio de atribución; el ejercicio de las competencias de la Unión se rige por:","o":["los principios de cooperación leal y subsidiariedad.","los principios de atribución y proporcionalidad.","los principios de subsidiariedad y seguridad jurídica.","los principios de subsidiariedad y proporcionalidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">los principios de subsidiariedad y proporcionalidad</mark></span>El <span class=\"ref-norma\">art. 5.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El ejercicio de las competencias de la Unión se rige por los principios de subsidiariedad y proporcionalidad\"</span>. Delimitación: atribución; ejercicio: subsidiariedad y proporcionalidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3347","p":"Tratado de Funcionamiento de la Unión Europea. Inmigración. La política común de inmigración no afectará al derecho de los Estados miembros a establecer volúmenes de admisión en su territorio de nacionales de terceros países procedentes de terceros países con el fin de:","o":["ejercer una actividad profesional altamente cualificada.","reunirse con familiares residentes legalmente en el territorio.","buscar trabajo por cuenta ajena o por cuenta propia.","cursar estudios o realizar actividades de investigación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">buscar trabajo por cuenta ajena o por cuenta propia</mark></span>El <span class=\"ref-norma\">art. 79.5 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con el fin de buscar trabajo por cuenta ajena o por cuenta propia\"</span>. Los Estados fijan los volúmenes de admisión de quienes buscan trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-392","p":"Tratado de la Unión Europea. Principios que delimitan las competencias de la Unión. En virtud del principio de atribución, la Unión actúa dentro de los límites de las competencias que le atribuyen los Estados miembros en los Tratados para lograr los objetivos que éstos determinan. Toda competencia no atribuida a la Unión en los Tratados corresponde a:","o":["Los Estados miembros.","La Unión, con carácter subsidiario.","Las instituciones de la Unión, por delegación.","Los Estados miembros, previa autorización del Consejo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 5.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"Toda competencia no atribuida a la Unión en los Tratados corresponde a los Estados miembros\"</span>. Lo no atribuido a la Unión queda en manos de los Estados miembros. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-ia-3212","p":"Tratado de la Unión Europea. Relación entre la PESC y las demás políticas. La ejecución de la política exterior y de seguridad común no afectará a la aplicación de los procedimientos y al alcance respectivo de las atribuciones de las instituciones establecidos en los Tratados para el ejercicio de:","o":["las competencias exclusivas de los Estados miembros en materia de defensa nacional.","las competencias de la Unión mencionadas en los artículos sobre categorías y ámbitos de competencia.","las competencias de ejecución de las instituciones en materia de política comercial, sin perjuicio de lo dispuesto en otras disposiciones.","las competencias de control de las instituciones en materia presupuestaria."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">las competencias de la Unión mencionadas en los artículos sobre categorías y ámbitos de competencia</mark></span>El <span class=\"ref-norma\">art. 40 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"para el ejercicio de las competencias de la Unión mencionadas en los artículos 3 a 6\"</span>. La PESC no afecta al ejercicio de las competencias de la Unión de los artículos 3 a 6 del TFUE (y viceversa). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-66","p":"Tratado de la Unión Europea. Las instituciones de la Unión aplicarán el principio de subsidiariedad de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad. ¿Quiénes velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el mencionado Protocolo?:","o":["Los parlamentos nacionales.","El Parlamento Europeo.","El Consejo.","El Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los parlamentos nacionales</mark></span>El <span class=\"ref-norma\">art. 5.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Las instituciones de la Unión aplicarán el principio de subsidiariedad de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad. Los Parlamentos nacionales velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el mencionado Protocolo\"</span>. El artículo 5.3 del TUE atribuye a los Parlamentos nacionales velar por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad."},{"i":"3-306","p":"Tratado de la Unión Europea. Las instituciones de la Unión aplicarán el principio de subsidiariedad de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad. ¿Quiénes velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el mencionado Protocolo?","o":["Los parlamentos nacionales.","El Parlamento Europeo.","El Consejo.","El Consejo Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Los parlamentos nacionales</mark></span>El <span class=\"ref-norma\">art. 5.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Las instituciones de la Unión aplicarán el principio de subsidiariedad de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad. Los Parlamentos nacionales velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el mencionado Protocolo\"</span>. El artículo 12 TUE atribuye a los parlamentos nacionales el velar por el respeto del principio de subsidiariedad conforme al Protocolo correspondiente."},{"i":"3-ia-3023","p":"Tratado de la Unión Europea. Principios que delimitan las competencias. En virtud del principio de subsidiariedad, en los ámbitos que no sean de su competencia exclusiva, la Unión intervendrá sólo en caso de que, y en la medida en que, los objetivos de la acción pretendida no puedan ser alcanzados de manera suficiente por los Estados miembros, ni a nivel central ni a nivel regional y local, sino que puedan alcanzarse mejor, debido a:","o":["la naturaleza o a la complejidad de la acción pretendida, por parte de la Unión.","la urgencia o a la gravedad de la acción pretendida, a escala de la Unión.","la dimensión o a los efectos de la acción pretendida, a escala de la Unión.","la dimensión o al coste de la acción pretendida, mediante la cooperación entre Estados."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la dimensión o a los efectos de la acción pretendida, a escala de la Unión</mark></span>El <span class=\"ref-norma\">art. 5.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"debido a la dimensión o a los efectos de la acción pretendida, a escala de la Unión\"</span>. La mejor realización a escala de la Unión se justifica por la dimensión o los efectos de la acción. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3024","p":"Tratado de la Unión Europea. Principios que delimitan las competencias. Las instituciones de la Unión aplicarán el principio de subsidiariedad de conformidad con el Protocolo sobre la aplicación de los principios de subsidiariedad y proporcionalidad; los Parlamentos nacionales:","o":["controlarán el respeto del principio de proporcionalidad mediante dictamen motivado del Parlamento Europeo, sin perjuicio de lo dispuesto en otras disposiciones.","velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el mencionado Protocolo.","participarán en el control de ambos principios a través de la Comisión de Asuntos Jurídicos.","velarán por el respeto de ambos principios con arreglo al procedimiento fijado por cada Estado."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido en el mencionado Protocolo</mark></span>El <span class=\"ref-norma\">art. 5.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los Parlamentos nacionales velarán por el respeto del principio de subsidiariedad con arreglo al procedimiento establecido\"</span>. Los Parlamentos nacionales velan por la subsidiariedad conforme al Protocolo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-393","p":"Tratado de la Unión Europea. Principios que delimitan las competencias de la Unión. En virtud del principio de proporcionalidad, el contenido y la forma de la acción de la Unión no excederán de lo necesario para alcanzar:","o":["Los objetivos de los Estados miembros.","Las competencias que les atribuyen los Estados miembros.","Los fines que fije la Comisión.","Los objetivos de los Tratados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los objetivos de los Tratados</mark></span>El <span class=\"ref-norma\">art. 5.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"el contenido y la forma de la acción de la Unión no excederán de lo necesario para alcanzar los objetivos de los Tratados\"</span>. Proporcionalidad: la acción de la Unión no va más allá de lo necesario para los objetivos de los Tratados. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-ia-3025","p":"Tratado de la Unión Europea. Principios que delimitan las competencias. En virtud del principio de proporcionalidad, el contenido y la forma de la acción de la Unión no excederán:","o":["de lo necesario para alcanzar los objetivos de los Tratados.","de lo necesario para alcanzar los objetivos de la acción pretendida.","de lo adecuado para garantizar el equilibrio entre las competencias.","de lo previsto para lograr los objetivos de las políticas de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de lo necesario para alcanzar los objetivos de los Tratados</mark></span>El <span class=\"ref-norma\">art. 5.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el contenido y la forma de la acción de la Unión no exce\"</span>. No excede de lo necesario para alcanzar los objetivos de los Tratados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 9 — Igualdad y ciudadanía de la Unión","q":[{"i":"3-94","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. La Unión respetará en todas sus actividades el principio de la igualdad de sus ciudadanos, que se beneficiarán por igual de la atención de:","o":["Sus instrumentos y organismos.","Sus instituciones y órganos.","Sus instituciones, órganos y organismos.","Sus órganos y organismos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Sus instituciones, órganos y organismos</mark></span>El <span class=\"ref-norma\">art. 9 del TUE</span> dispone: <span class=\"ref-concepto\">\"La Unión respetará en todas sus actividades el principio de la igualdad de sus ciudadanos, que se beneficiarán por igual de la atención de sus instituciones, órganos y organismos. Será ciudadano de la Unión toda persona que tenga la nacionalidad de un Estado miembro. La ciudadanía de la Unión se añade a la ciudadanía nacional sin sustituirla\"</span>. El artículo 9 del TUE establece que la Unión respetará en todas sus actividades el principio de la igualdad de sus ciudadanos, que se beneficiarán por igual de la atención de sus instituciones, órganos y organismos."},{"i":"3-346","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Servicios. En tanto no se supriman las restricciones a la libre prestación de servicios, cada uno de los Estados miembros aplicará tales restricciones a todos los prestadores de servicios, sin distinción de:","o":["Nacionalidad o profesión.","Residencia o actividad.","Origen o domicilio fiscal.","Nacionalidad o residencia."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Nacionalidad o residencia</mark></span>El <span class=\"ref-norma\">art. 61 del TFUE</span> dispone: <span class=\"ref-concepto\">\"aplicará tales restricciones, sin distinción de nacionalidad o residencia, a todos los prestadores de servicios\"</span>. Sin distinción de nacionalidad o residencia."},{"i":"3-167","p":"Tratado de la Unión Europea. Señale la INCORRECTA:","o":["La Unión respetará en todas sus actividades el principio de la igualdad de sus ciudadanos, que se beneficiarán por igual de la atención de sus instituciones, órganos y organismos.","Será ciudadano de la Unión toda persona que tenga la nacionalidad de un Estado miembro.","La ciudadanía de la Unión no se añade a la ciudadanía nacional sin sustituirla.","Los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La ciudadanía de la Unión no se añade a la ciudadanía nacional sin sustituirla</mark></span>La C niega lo que dice el texto. A y B reproducen el art. 9 y D el art. 10.2. Según el <span class=\"ref-norma\">art. 9 del TUE</span>: <span class=\"ref-concepto\">\"Será ciudadano de la Unión toda persona que tenga la nacionalidad de un Estado miembro. La ciudadanía de la Unión se añade a la ciudadanía nacional sin sustituirla.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3038","p":"Tratado de la Unión Europea. Principio de igualdad democrática. La Unión respetará en todas sus actividades el principio de la igualdad de sus ciudadanos; será ciudadano de la Unión toda persona que tenga la nacionalidad de un Estado miembro, y la ciudadanía de la Unión:","o":["se superpone a la ciudadanía nacional y la sustituye parcialmente.","se reconoce de forma independiente a la ciudadanía nacional.","se adquiere por residencia legal en el territorio de la Unión.","se añade a la ciudadanía nacional sin sustituirla."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se añade a la ciudadanía nacional sin sustituirla</mark></span>El <span class=\"ref-norma\">art. 9 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"La ciudadanía de la Unión se añade a la ciudadanía nacional sin sustituirla\"</span>. La ciudadanía de la Unión es complementaria y no sustituye a la nacional. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 10 — Democracia representativa R5","q":[{"i":"3-201","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. El funcionamiento de la Unión se basa en:","o":["La democracia parlamentaria.","La democracia asamblearia.","La democracia representativa.","La democracia permanente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">La democracia representativa</mark></span>El <span class=\"ref-norma\">art. 10.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"El funcionamiento de la Unión se basa en la democracia representativa\"</span>. El artículo 10.1 del TUE establece que el funcionamiento de la Unión se basa en la democracia representativa."},{"i":"3-9","p":"Tratado de la Unión Europea. Los ciudadanos estarán directamente representados en la Unión a través de:","o":["El Parlamento Europeo.","La Comisión Europea.","El Consejo de la Unión Europea.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 10.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo\"</span>. El artículo 10.2 del TUE dispone que los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo, mientras que los Estados miembros lo están en el Consejo Europeo y en el Consejo."},{"i":"3-192","p":"Tratado de la Unión Europea. Los ciudadanos estarán directamente representados en la Unión a través de:","o":["Consejo Europeo.","Parlamento Europeo.","Consejo de la Unión Europea.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 10.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo\"</span>. El artículo 10.2 del TUE establece que los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo."},{"i":"3-232","p":"Tratado de la Unión Europea. Los ciudadanos estarán directamente representados en la Unión a través de:","o":["El Defensor del Pueblo.","El Parlamento Europeo.","Las Cortes Generales.","El Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 10.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"Los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo\"</span>. El artículo 10.2 del TUE establece que los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo."},{"i":"3-ia-3039","p":"Tratado de la Unión Europea. Democracia representativa. El funcionamiento de la Unión se basa en la democracia representativa; los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo y los Estados miembros estarán representados en el Consejo Europeo por:","o":["sus ministros de Asuntos Exteriores.","sus representantes permanentes.","su Jefe de Estado o de Gobierno.","su Jefe de Estado exclusivamente."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">su Jefe de Estado o de Gobierno</mark></span>El <span class=\"ref-norma\">art. 10.1 y 2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los Estados miembros estarán representados en el Consejo Europeo por su Jefe de Estado o de Go\"</span>. En el Consejo Europeo, el Jefe de Estado o de Gobierno; en el Consejo, los Gobiernos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-42","p":"Tratado de la Unión Europea. Los Estados miembros estarán representados por sus Gobiernos en:","o":["El Consejo Europeo.","El Consejo.","El Parlamento Europeo.","La Comisión Europea."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 10.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los Estados miembros estarán representados en el Consejo Europeo por su Jefe de Estado o de Gobierno y en el Consejo por sus Gobiernos, que serán democráticamente responsables, bien ante sus Parlamentos nacionales, bien ante sus ciudadanos\"</span>. El artículo 10.2 del TUE establece que los Estados miembros estarán representados en el Consejo por sus Gobiernos, mientras que en el Consejo Europeo lo están por su Jefe de Estado o de Gobierno."},{"i":"3-127","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. Los Estados miembros estarán representados en __________ por sus Gobiernos, que serán democráticamente responsables, bien ante sus Parlamentos nacionales, bien ante sus ciudadanos.","o":["El Consejo Europeo.","El Consejo.","El Parlamento Europeo.","La Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 10.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los Estados miembros estarán representados en el Consejo Europeo por su Jefe de Estado o de Gobierno y en el Consejo por sus Gobiernos, que serán democráticamente responsables, bien ante sus Parlamentos nacionales, bien ante sus ciudadanos\"</span>. El artículo 10.2 del TUE establece que los Estados miembros estarán representados en el Consejo por sus Gobiernos, que serán democráticamente responsables ante sus Parlamentos nacionales o ante sus ciudadanos."},{"i":"3-ia-3040","p":"Tratado de la Unión Europea. Democracia representativa. Los Estados miembros estarán representados en el Consejo por sus Gobiernos, que serán democráticamente responsables:","o":["ante el Parlamento Europeo y ante sus Parlamentos nacionales, sin perjuicio de lo dispuesto en otras disposiciones.","bien ante sus Parlamentos nacionales, bien ante sus ciudadanos.","ante sus Parlamentos nacionales y ante el Consejo Europeo.","ante sus ciudadanos y ante el Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">bien ante sus Parlamentos nacionales, bien ante sus ciudadanos</mark></span>El <span class=\"ref-norma\">art. 10.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"que serán democráticamente responsables, bien ante sus Parlamentos nacionales, bien ante sus ciudadanos\"</span>. Responden bien ante los Parlamentos nacionales, bien ante los ciudadanos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-394","p":"Tratado de la Unión Europea. Principios democráticos. Todo ciudadano tiene derecho a participar en la vida democrática de la Unión. Las decisiones serán tomadas de la forma:","o":["Más transparente y próxima posible a los ciudadanos.","Más abierta y directa posible para los ciudadanos.","Más abierta y próxima posible a los ciudadanos.","Más amplia y próxima posible a los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Más abierta y próxima posible a los ciudadanos</mark></span>El <span class=\"ref-norma\">art. 10.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"Las decisiones serán tomadas de la forma más abierta y próxima posible a los ciudadanos\"</span>. Se repite la fórmula del primer artículo: «abierta y próxima a los ciudadanos». <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-53","p":"Tratado de la Unión Europea. ¿Quiénes contribuirán a formar la conciencia política europea y a expresar la voluntad de los ciudadanos de la Unión?","o":["El Parlamento Europeo.","Los ciudadanos.","Los partidos políticos a escala europea.","Las instituciones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los partidos políticos a escala europea</mark></span>El <span class=\"ref-norma\">art. 10.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los partidos políticos a escala europea contribuirán a formar la conciencia política europea y a expresar la voluntad de los ciudadanos de la Unión\"</span>. El artículo 10.4 del TUE dispone que los partidos políticos a escala europea contribuirán a formar la conciencia política europea y a expresar la voluntad de los ciudadanos de la Unión."},{"i":"3-ia-3041","p":"Tratado de la Unión Europea. Democracia representativa. Todo ciudadano tiene derecho a participar en la vida democrática de la Unión y los partidos políticos a escala europea contribuirán a formar la conciencia política europea y a:","o":["expresar la voluntad de los ciudadanos de la Unión.","garantizar la representación de los ciudadanos de la Unión.","promover la participación de los ciudadanos de la Unión.","canalizar las demandas de los ciudadanos de la Unión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">expresar la voluntad de los ciudadanos de la Unión</mark></span>El <span class=\"ref-norma\">art. 10.3 y 4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"contribuirán a formar la conciencia política europea y a expresar la voluntad de los ciudadanos de la Unión\"</span>. Los partidos europeos forman la conciencia política europea y expresan la voluntad de los ciudadanos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 11 — Participación e iniciativa ciudadana ✱","q":[{"i":"3-10","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. ¿Quiénes darán a los ciudadanos y a las asociaciones representativas, por los cauces apropiados, la posibilidad de expresar e intercambiar públicamente sus opiniones en todos los ámbitos de actuación de la Unión?","o":["El Parlamento Europeo.","Los ciudadanos.","Los partidos políticos a escala europea.","Las instituciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las instituciones</mark></span>El <span class=\"ref-norma\">art. 11.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Las instituciones darán a los ciudadanos y a las asociaciones representativas, por los cauces apropiados, la posibilidad de expresar e intercambiar públicamente sus opiniones en todos los ámbitos de actuación de la Unión\"</span>. El artículo 11.1 del TUE atribuye a las instituciones la obligación de dar a los ciudadanos y a las asociaciones representativas, por los cauces apropiados, la posibilidad de expresar e intercambiar públicamente sus opiniones en todos los ámbitos de actuación de la Unión."},{"i":"3-4","p":"Tratado de la Unión Europea. Las instituciones mantendrán un diálogo ___________ transparente y regular con las asociaciones representativas y la sociedad civil.","o":["Postulado.","Abierto.","Representativo.","Todas son incorrectas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Abierto</mark></span>El <span class=\"ref-norma\">art. 11.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Las instituciones mantendrán un diálogo abierto, transparente y regular con las asociaciones representativas y la sociedad civil\"</span>. El artículo 11.2 del TUE señala que las instituciones mantendrán un diálogo abierto, transparente y regular con las asociaciones representativas y la sociedad civil."},{"i":"3-118","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. Las Instituciones mantendrán un diálogo _________ con las asociaciones representativas y la sociedad civil. Señale la incorrecta.","o":["Abierto.","Transparente.","Directo.","Regular."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Directo</mark></span>El <span class=\"ref-norma\">art. 11.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Las instituciones mantendrán un diálogo abierto, transparente y regular con las asociaciones representativas y la sociedad civil\"</span>. La opción correcta es la C, por ser la incorrecta. El artículo 11.2 del TUE exige que el diálogo con las asociaciones representativas y la sociedad civil sea abierto, transparente y regular, sin mencionar que deba ser 'directo'."},{"i":"3-139","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. Las instituciones mantendrán un diálogo ______ con las asociaciones representativas y la sociedad civil. Señale la incorrecta.","o":["Abierto.","Conciso.","Transparente.","Regular."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Conciiso</mark></span>El <span class=\"ref-norma\">art. 11.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Las instituciones mantendrán un diálogo abierto, transparente y regular con las asociaciones representativas y la sociedad civil\"</span>. La opción correcta es la B, por ser la incorrecta. El artículo 11.2 del TUE exige que el diálogo con las asociaciones representativas y la sociedad civil sea abierto, transparente y regular, sin que se mencione que deba ser 'conciso'."},{"i":"3-ia-3043","p":"Tratado de la Unión Europea. Participación ciudadana. Con objeto de garantizar la coherencia y la transparencia de las acciones de la Unión, la Comisión Europea mantendrá:","o":["consultas obligatorias con el Parlamento Europeo.","consultas periódicas con los Parlamentos nacionales.","amplias consultas con las partes interesadas.","amplias consultas con los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">amplias consultas con las partes interesadas</mark></span>El <span class=\"ref-norma\">art. 11.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la Comisión Eu-ropea mantendrá amplias consultas con las partes interesadas\"</span>. La Comisión mantiene amplias consultas con las partes interesadas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-193","p":"Tratado de la Unión Europea. ¿Cuántos ciudadanos podrán tomar la iniciativa de invitar a la Comisión Europea, en el marco de sus atribuciones, a que presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión?","o":["Un grupo de al menos doscientos cincuenta mil que sean nacionales de un número significativo de Estados miembros.","Un grupo de al menos quinientos mil que sean nacionales de un número significativo de Estados miembros.","Un grupo de al menos un millón de ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros.","Un grupo de al menos dos millones que sean nacionales de un número significativo de Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Un grupo de al menos un millón de ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros</mark></span>El <span class=\"ref-norma\">art. 11.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Un grupo de al menos un millón de ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros, podrá tomar la iniciativa de invitar a la Comisión Europea, en el marco de sus atribuciones, a que presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión para los fines de la aplicación de los Tratados\"</span>. El artículo 11.4 del TUE establece que un grupo de al menos un millón de ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros, podrá tomar la iniciativa de invitar a la Comisión Europea a que presente una propuesta."},{"i":"3-41","p":"Tratado de la Unión Europea. Disposiciones sobre los principios democráticos. Señale la opción incorrecta en esta materia:","o":["Los ciudadanos estarán directamente representados en la Unión a través del Parlamento Europeo.","Los Estados miembros estarán representados en el Consejo Europeo por su Jefe de Estado o de Gobierno y en el Consejo por sus Gobiernos, que serán democráticamente responsables, bien ante sus parlamentos nacionales, bien ante sus ciudadanos.","Todo ciudadano tiene derecho a participar en la vida democrática de la Unión. Las decisiones serán tomadas de la forma más abierta y próxima posible a los ciudadanos.","Un grupo de al menos quinientos mil ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros, podrá tomar la iniciativa de invitar a la Comisión Europea, en el marco de sus atribuciones, a que presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión para los fines de la aplicación de los Tratados."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Un grupo de al menos quinientos mil ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros, podrá tomar la iniciativa de invitar a la Comisión Europea, en el marco de sus atribuciones, a que presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión para los fines de la aplicación de los Tratados</mark></span>El <span class=\"ref-norma\">art. 11.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Un grupo de al menos un millón de ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros, podrá tomar la iniciativa de invitar a la Comisión Europea, en el marco de sus atribuciones, a que presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión para los fines de la aplicación de los Tratados\"</span>. La opción correcta es la D, por ser la incorrecta que pide el enunciado. El artículo 11.4 del TUE exige un grupo de al menos un millón de ciudadanos de la Unión, y no quinientos mil, para poder tomar la iniciativa de invitar a la Comisión a presentar una propuesta."},{"i":"3-ia-3044","p":"Tratado de la Unión Europea. Participación ciudadana. Un grupo de al menos un millón de ciudadanos de la Unión, que sean nacionales de un número significativo de Estados miembros, podrá tomar la iniciativa de invitar a la Comisión Europea, en el marco de sus atribuciones, a que:","o":["adopte un acto jurídico sobre cuestiones que estos ciudadanos estimen que requieren una acción urgente, sin perjuicio de lo dispuesto en otras disposiciones.","presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión.","someta una propuesta legislativa al Parlamento Europeo sobre cuestiones de interés general.","presente un informe sobre cuestiones que estos ciudadanos estimen que afectan a sus derechos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico de la Unión</mark></span>El <span class=\"ref-norma\">art. 11.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a que presente una propuesta adecuada sobre cuestiones que estos ciudadanos estimen que requieren un acto jurídico\"</span>. Es la iniciativa ciudadana europea: un millón de ciudadanos de un número significativo de Estados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 13 — Marco institucional R6","q":[{"i":"3-218","p":"Tratado de Funcionamiento de la Unión Europea. Se constituirá un comité para que se pronuncie sobre la idoneidad de los candidatos para el ejercicio de las funciones de juez y abogado general del Tribunal de Justicia y del Tribunal General. ¿Por cuántas personalidades estará integrado dicho comité?","o":["Cinco.","Seis.","Siete.","Ocho."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Siete</mark></span>El <span class=\"ref-norma\">art. 255 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El comité estará compuesto por siete personalidades elegidas de entre antiguos miembros del Tribunal de Justicia y del Tribunal General, miembros de los órganos jurisdiccionales nacionales superiores y juristas de reconocida competencia, uno de los cuales será propuesto por el Parlamento Europeo\"</span>. El artículo 255 del TFUE establece que el comité que se pronuncia sobre la idoneidad de los candidatos a juez y abogado general del Tribunal de Justicia y del Tribunal General estará compuesto por siete personalidades."},{"i":"3-17","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. La Unión dispone de un marco institucional que tiene como finalidad:","o":["Promover sus valores.","Perseguir sus objetivos.","Defender sus intereses, los de sus ciudadanos y los de los Estados miembros.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 13.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión dispone de un marco institucional que tiene como finalidad promover sus valores, perseguir sus objetivos, defender sus intereses, los de sus ciudadanos y los de los Estados miembros, así como garantizar la coherencia, eficacia y continuidad de sus políticas y acciones. \u0007Las instituciones de la Unión son\"</span>. El artículo 13.1 del TUE establece que la Unión dispone de un marco institucional que tiene como finalidad promover sus valores, perseguir sus objetivos, defender sus intereses, los de sus ciudadanos y los de los Estados miembros, así como garantizar la coherencia, eficacia y continuidad de sus políticas y acciones."},{"i":"3-ia-3048","p":"Tratado de la Unión Europea. Marco institucional. La Unión dispone de un marco institucional que tiene como finalidad promover sus valores, perseguir sus objetivos, defender sus intereses, los de sus ciudadanos y los de los Estados miembros, así como garantizar:","o":["la coordinación, eficacia y transparencia de sus políticas y acciones.","la coherencia, eficacia y continuidad de sus políticas y acciones.","la legalidad, eficacia y continuidad de sus políticas y acciones.","la coherencia, eficacia y transparencia de sus políticas y acciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la coherencia, eficacia y continuidad de sus políticas y acciones</mark></span>El <span class=\"ref-norma\">art. 13.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"así como garantizar la coherencia, eficacia y continuidad de sus políticas y acciones\"</span>. El marco garantiza coherencia, eficacia y continuidad. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-3","p":"Tratado de Funcionamiento de la Unión Europea. Órganos consultivos de la Unión. ¿Qué organismos estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones, que ejercerán funciones consultivas? Señale la INCORRECTA.","o":["El Parlamento Europeo.","El Consejo.","La Comisión.","El Tribunal de Justicia de la Unión Europea."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Tribunal de Justicia de la Unión Europea</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. Según el artículo 13.4 del TUE, el Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas; el Tribunal de Justicia de la Unión Europea no figura entre estas instituciones asistidas."},{"i":"3-236","p":"Tratado de la Unión Europea. Disposiciones sobre las Instituciones. ¿A quién NO asistirá el Comité Económico y Social?","o":["Al Consejo.","A la Comisión.","Al Parlamento Europeo.","Al Consejo Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. El artículo 300.1 del TFUE establece que el Parlamento Europeo, el Consejo y la Comisión estarán asistidos por el Comité Económico y Social y el Comité de las Regiones, sin incluir al Consejo Europeo entre las instituciones asistidas."},{"i":"3-58","p":"Tratado de la Unión Europea. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por:","o":["Comité Económico y Social.","Comité de las Regiones.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. El artículo 300.1 del TFUE dispone que el Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones, que ejercerán funciones consultivas."},{"i":"3-300","p":"Tratado de la Unión Europea. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por:","o":["Comité Económico y Social.","Comité de las Regiones.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. El artículo 13.4 TUE dispone que el Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y un Comité de las Regiones, que ejercerán funciones consultivas."},{"i":"3-13","p":"Tratado de la Unión Europea. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité de las Regiones que ejercerán funciones:","o":["De representación.","De control.","De colaboración.","Consultivas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Consultivas</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. El artículo 13.4 del TUE señala que el Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas."},{"i":"3-319","p":"Tratado de la Unión Europea. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité de las Regiones que ejercerán funciones:","o":["De representación.","De control.","De colaboración.","Consultivas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Consultivas</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. El artículo 13.4 TUE atribuye al Comité de las Regiones funciones consultivas."},{"i":"3-ia-3051","p":"Tratado de la Unión Europea. Marco institucional. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán:","o":["funciones de control.","funciones de iniciativa.","funciones consultivas.","funciones de coordinación."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">funciones consultivas</mark></span>El <span class=\"ref-norma\">art. 13.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. Los dos Comités tienen funciones consultivas. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"PARLAMENTO EUROPEO art. 14 · cuadro del temario","q":[{"i":"3-22","p":"Tratado de la Unión Europea. El Presidente de la Comisión lo elegirá:","o":["El Parlamento Europeo.","El Consejo Europeo.","El Consejo.","La propia Comisión Europea."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 14.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El PARLAMENTO EUROPEO ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria. Ejercerá funciones de control político y consultivas, en las condiciones establecidas en los Tratados. Elegirá al Presidente de la Comisión\"</span>. El artículo 14.1 del TUE dispone que el Parlamento Europeo elegirá al Presidente de la Comisión, si bien el candidato es previamente propuesto por el Consejo Europeo conforme al artículo 17.7."},{"i":"3-63","p":"Tratado de la Unión Europea. El Parlamento Europeo. Señale la incorrecta.","o":["Ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria.","Ejercerá funciones de control político y consultivas, en las condiciones establecidas en los Tratados.","Elegirá al Presidente de la Comisión.","Estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos, más el Presidente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos, más el Presidente</mark></span>El <span class=\"ref-norma\">art. 14.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos cincuenta, más el Presidente\"</span>. Es la incorrecta: según el art. 14.2 TUE el número no excederá de setecientos CINCUENTA, más el Presidente (no setecientos)."},{"i":"3-92","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. Señale la incorrecta.","o":["El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión.","Su número no excederá de setecientos cincuenta, más el Presidente.","La representación de los ciudadanos será de forma decreciente proporcional, con un mínimo de seis diputados por Estado miembro.","No se asignará a ningún Estado miembro más de ochenta y seis escaños."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">No se asignará a ningún Estado miembro más de ochenta y seis escaños</mark></span>El <span class=\"ref-norma\">art. 14.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"No se asignará a ningún Estado miembro más de noventa y seis escaños\"</span>. La opción correcta es la D, por ser la incorrecta. El artículo 14.2 del TUE establece que no se asignará a ningún Estado miembro más de noventa y seis escaños, y no ochenta y seis como indica erróneamente la opción D."},{"i":"3-141","p":"Tratado de la Unión Europea. Disposiciones sobre las Instituciones. Los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de:","o":["Cuatro años.","Cinco años.","Tres años.","Seis años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 14.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de cinco años\"</span>. El artículo 14.3 del TUE establece que los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de cinco años."},{"i":"3-148","p":"Tratado de la Unión Europea. Disposiciones sobre las Instituciones. El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de ______ más el Presidente.","o":["Setecientos cincuenta.","Seiscientos cincuenta.","Quinientos cincuenta.","Ochocientos cincuenta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Setecientos cincuenta</mark></span>El <span class=\"ref-norma\">art. 14.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos cincuenta, más el Presidente\"</span>. El artículo 14.2 del TUE establece que el número de diputados del Parlamento Europeo no excederá de setecientos cincuenta, más el Presidente."},{"i":"3-159","p":"Tratado de la Unión Europea. Los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de:","o":["3 años.","5 años.","4 años.","6 años."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">5 años</mark></span>El <span class=\"ref-norma\">art. 14.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de cinco años\"</span>. El artículo 14.3 del TUE establece que los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de cinco años."},{"i":"3-210","p":"Tratado de la Unión Europea. El Parlamento Europeo estará compuesto por:","o":["Los Gobiernos de los Estados miembros.","Los Jefes de Gobierno de los Estados miembros.","Representantes de los ciudadanos de la Unión.","Ministros de los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Representantes de los ciudadanos de la Unión</mark></span>El <span class=\"ref-norma\">art. 14.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión\"</span>. El artículo 14.2 del TUE establece que el Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión."},{"i":"3-303","p":"Tratado de la Unión Europea. El Parlamento Europeo. Señale la incorrecta.","o":["Ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria.","Ejercerá funciones de control político y consultivas, en las condiciones establecidas en los Tratados.","Elegirá al Presidente de la Comisión.","Estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos, más el Presidente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos, más el Presidente</mark></span>El <span class=\"ref-norma\">art. 14.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión. Su número no excederá de setecientos cincuenta, más el Presidente\"</span>. El artículo 14.2 TUE fija el límite en setecientos cincuenta diputados, más el Presidente; las demás afirmaciones son correctas conforme al artículo 14 TUE."},{"i":"3-325","p":"Tratado de la Unión Europea. El Parlamento Europeo estará compuesto por:","o":["Los Gobiernos de los Estados miembros.","Los Jefes de Gobierno de los Estados miembros.","Representantes de los ciudadanos de la Unión.","Ministros de los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Representantes de los ciudadanos de la Unión</mark></span>El <span class=\"ref-norma\">art. 14.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión\"</span>. El artículo 14.2 TUE establece que el Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión."},{"i":"3-ia-3052","p":"Tratado de la Unión Europea. Parlamento Europeo. El Parlamento Europeo ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria; además, ejercerá funciones de control político y consultivas y elegirá:","o":["al Presidente del Consejo Europeo.","al Presidente de la Comisión.","al Alto Representante de la Unión.","a los miembros del Tribunal de Cuentas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">al Presidente de la Comisión</mark></span>El <span class=\"ref-norma\">art. 14.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Ejercerá funciones de control político y consultivas, en las condiciones establecidas en los Tratados. Elegirá al Presidente de la Comisión\"</span>. El Parlamento elige al Presidente de la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3053","p":"Tratado de la Unión Europea. Parlamento Europeo. El Parlamento Europeo estará compuesto por representantes de los ciudadanos de la Unión; su número no excederá de setecientos cincuenta, más el Presidente, con un mínimo de seis diputados por Estado miembro y sin que se asigne a ningún Estado miembro más de:","o":["noventa y seis escaños.","ochenta y cuatro escaños.","ciento cinco escaños.","noventa y nueve escaños."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">noventa y seis escaños</mark></span>El <span class=\"ref-norma\">art. 14.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"No se asignará a ningún Estado miembro más de noventa y seis escaños\"</span>. El máximo es de noventa y seis escaños por Estado miembro. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3054","p":"Tratado de la Unión Europea. Parlamento Europeo. La composición del Parlamento Europeo se fija mediante una decisión que adoptará el Consejo Europeo:","o":["por mayoría cualificada, a propuesta de la Comisión y con aprobación del Parlamento.","por unanimidad, a propuesta de la Comisión y previa consulta al Parlamento.","por mayoría cualificada, a iniciativa del Parlamento Europeo y con su aprobación.","por unanimidad, a iniciativa del Parlamento Europeo y con su aprobación."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">por unanimidad, a iniciativa del Parlamento Europeo y con su aprobación</mark></span>El <span class=\"ref-norma\">art. 14.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo adoptará por unanimidad, a iniciativa del Parlamento Europeo y con su aproba-ción, una decisión por la que se fije la composición del Parlamento Europeo\"</span>. Unanimidad del Consejo Europeo, a iniciativa y con aprobación del Parlamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3055","p":"Tratado de la Unión Europea. Parlamento Europeo. Los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de:","o":["cuatro años.","seis años.","cinco años.","siete años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">cinco años</mark></span>El <span class=\"ref-norma\">art. 14.3 y 4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los diputados al Parlamento Europeo serán elegidos por sufragio universal directo, libre y secreto, para un mandato de cinco años\"</span>. El mandato es de cinco años. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"EL CONSEJO art. 16 · cuadros del temario","q":[{"i":"3-2","p":"Tratado de la Unión Europea. El Consejo se pronunciará:","o":["Por consenso, excepto cuando los Tratados dispongan otra cosa.","Por unanimidad, excepto cuando los Tratados dispongan otra cosa.","Por mayoría absoluta, excepto cuando los Tratados dispongan otra cosa.","Por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa</mark></span>El <span class=\"ref-norma\">art. 16.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo se pronunciará por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa\"</span>. El artículo 16.3 del TUE dispone que el Consejo se pronunciará por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa, siendo esta la regla general de votación en dicha institución."},{"i":"3-62","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo:","o":["El 70% de la población de la Unión.","El 75% de la población de la Unión.","El 60% de la población de la Unión.","El 65% de la población de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El 65% de la población de la Unión</mark></span>El <span class=\"ref-norma\">art. 16.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión\"</span>. El artículo 16.4 del TUE define que, a partir del 1 de noviembre de 2014, la mayoría cualificada se define como un mínimo del 55% de los miembros del Consejo, que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión."},{"i":"3-138","p":"Tratado de la Unión Europea. Disposiciones sobre las Instituciones. El Consejo. Una minoría de bloqueo estará compuesta por al menos ______ a falta de lo cual la mayoría cualificada será alcanzada.","o":["Cinco miembros del Consejo.","Cuatro miembros del Consejo.","Tres miembros del Consejo.","Dos miembros del Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Cuatro miembros del Consejo</mark></span>El <span class=\"ref-norma\">art. 16.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Una minoría de bloqueo estará compuesta por al menos cuatro miembros del Consejo, a falta de lo cual la mayoría cualificada se considerará alcanzada\"</span>. El artículo 16.4 del TUE establece que una minoría de bloqueo estará compuesta por al menos cuatro miembros del Consejo, a falta de lo cual la mayoría cualificada se considerará alcanzada."},{"i":"3-164","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. ¿Quién ejerce la función legislativa y la función presupuestaria?","o":["El Parlamento Europeo lo ejercerá conjuntamente con el Tribunal de Cuentas.","El Parlamento Europeo lo ejercerá conjuntamente con el Consejo.","El Parlamento Europeo lo ejercerá conjuntamente con el Banco Central Europeo.","El Parlamento Europeo lo ejercerá conjuntamente con el Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Parlamento Europeo lo ejercerá conjuntamente con el Consejo</mark></span>El <span class=\"ref-norma\">art. 16.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El CONSEJO ejercerá conjuntamente con el Parlamento Europeo la función legislativa y la función presupuestaria. Ejercerá funciones de definición de políticas y de coordinación, en las condiciones establecidas en los Tratados\"</span>. El artículo 14.1 del TUE dispone que el Parlamento Europeo ejercerá conjuntamente con el Consejo la función legislativa y la función presupuestaria."},{"i":"3-170","p":"Tratado de la Unión Europea. El Consejo estará compuesto por:","o":["Un representante de cada Estado miembro, con rango de embajador.","Un representante de cada Estado miembro, de rango ministerial.","Un representante de cada Estado miembro, con rango de Secretario de Estado.","Un representante de cada Estado miembro, con rango de Director General."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un representante de cada Estado miembro, de rango ministerial</mark></span>El <span class=\"ref-norma\">art. 16.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo estará compuesto por un representante de cada Estado miembro, de rango ministerial, facultado para comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho de voto\"</span>. El artículo 16.2 del TUE establece que el Consejo estará compuesto por un representante de cada Estado miembro, de rango ministerial, facultado para comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho de voto."},{"i":"3-190","p":"Tratado de la Unión Europea. Consejo. A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como _____________ que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión.","o":["Un máximo del 45% de los miembros del Consejo.","Un mínimo del 55% de los miembros del Consejo.","Un mínimo del 65% de los miembros del Consejo.","Un máximo del 55% de los miembros del Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Un mínimo del 55% de los miembros del Consejo</mark></span>El <span class=\"ref-norma\">art. 16.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión\"</span>. El artículo 16.4 del TUE establece que, a partir del 1 de noviembre de 2014, la mayoría cualificada se define como un mínimo del 55% de los miembros del Consejo, que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión."},{"i":"3-243","p":"Tratado de la Unión Europea. El Consejo. A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión3. Una minoría de bloqueo estará compuesta por al menos _____ miembros del Consejo, a falta de lo cual la mayoría cualificada se considerará alcanzada.","o":["Cuatro.","Cinco.","Tres.","Seis."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cuatro</mark></span>El <span class=\"ref-norma\">art. 16.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión. \u0007Una minoría de bloqueo estará compuesta por al menos cuatro miembros del Consejo, a falta de lo cual la mayoría cualificada se considerará alcanzada\"</span>. (The blocking minority must include at least four members of the Council.)"},{"i":"3-302","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo:","o":["El 70% de la población de la Unión.","El 75% de la población de la Unión.","El 60% de la población de la Unión.","El 65% de la población de la Unión."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El 65% de la población de la Unión</mark></span>El <span class=\"ref-norma\">art. 16.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55% de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo el 65% de la población de la Unión\"</span>. El artículo 16.4 TUE exige que la mayoría cualificada represente Estados miembros que reúnan como mínimo el 65% de la población de la Unión."},{"i":"3-316","p":"Tratado de la Unión Europea. El Consejo se pronunciará:","o":["Por consenso, excepto cuando los Tratados dispongan otra cosa.","Por unanimidad, excepto cuando los Tratados disponga otra cosa.","Por mayoría absoluta, excepto cuando los Tratados dispongan otra cosa.","Por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa</mark></span>El <span class=\"ref-norma\">art. 16.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo se pronunciará por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa\"</span>. El artículo 16.3 TUE establece la mayoría cualificada como regla general de votación del Consejo."},{"i":"3-395","p":"Tratado de la Unión Europea. El Consejo. El Consejo de Asuntos Generales velará por la coherencia de los trabajos de las diferentes formaciones del Consejo. Preparará las reuniones del Consejo Europeo y garantizará su actuación subsiguiente, en contacto con:","o":["El Alto Representante y la Comisión.","El Presidente del Consejo Europeo y la Comisión.","El Presidente del Parlamento Europeo y el Alto Representante.","El Presidente del Consejo Europeo y el Parlamento Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Presidente del Consejo Europeo y la Comisión</mark></span>El <span class=\"ref-norma\">art. 16.6 del TUE</span> dispone: <span class=\"ref-concepto\">\"en contacto con el Presidente del Consejo Europeo y la Comisión\"</span>. El Consejo de Asuntos Generales prepara las reuniones del Consejo Europeo. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-ia-3101","p":"Tratado de la Unión Europea. El Consejo. El Consejo ejercerá conjuntamente con el Parlamento Europeo la función legislativa y la función presupuestaria, y ejercerá además:","o":["funciones de definición de políticas y de coordinación, en las condiciones establecidas en los Tratados.","funciones de control político y consultivas, en las condiciones establecidas en los Tratados.","funciones de impulso político y de representación exterior, en las condiciones fijadas por el Consejo Europeo.","funciones de ejecución y de gestión del presupuesto, en las condiciones establecidas en los Tratados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">funciones de definición de políticas y de coordinación, en las condiciones establecidas en los Tratados</mark></span>El <span class=\"ref-norma\">art. 16.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Ejercerá funciones de definición de políticas y de coordinación, en las condiciones\"</span>. El Consejo define políticas y coordina; el control político corresponde al Parlamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3102","p":"Tratado de la Unión Europea. El Consejo. El Consejo estará compuesto por un representante de cada Estado miembro, de rango ministerial, facultado para:","o":["representar al Estado miembro ante las demás instituciones y para ejercer el derecho de iniciativa.","comprometer al Parlamento nacional del Estado miembro al que represente y ejercer el derecho de voto.","negociar en nombre del Estado miembro y proponer actos legislativos a la Comisión Europea.","comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho de voto."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">comprometer al Gobierno del Estado miembro al que represente y para ejercer el derecho de voto</mark></span>El <span class=\"ref-norma\">art. 16.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"facultado para comprometer al Gobierno del Estado miembro al que represente y para ejercer el de-recho de voto\"</span>. Es un representante de rango ministerial facultado para comprometer al Gobierno y votar. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3103","p":"Tratado de la Unión Europea. El Consejo. El Consejo se pronunciará por mayoría cualificada, excepto cuando:","o":["el Consejo Europeo disponga otra cosa.","un Estado miembro invoque un interés vital.","los Tratados dispongan otra cosa.","la Comisión así lo proponga."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">los Tratados dispongan otra cosa</mark></span>El <span class=\"ref-norma\">art. 16.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por mayoría cualificada, excepto cuando los Tratados dispongan otra cosa\"</span>. La regla general es la mayoría cualificada, salvo disposición en contrario de los Tratados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3104","p":"Tratado de la Unión Europea. El Consejo. A partir del 1 de noviembre de 2014, la mayoría cualificada se definirá como un mínimo del 55 % de los miembros del Consejo que incluya al menos a quince de ellos y represente a Estados miembros que reúnan como mínimo:","o":["el 62 % de la población de la Unión, sin perjuicio de lo dispuesto en otras disposiciones.","el 65 % de la población de la Unión.","el 72 % de la población de la Unión.","el 60 % de la población de la Unión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el 65 % de la población de la Unión</mark></span>El <span class=\"ref-norma\">art. 16.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"que reúnan como mínimo el 65% de la población de la Unión\"</span>. Doble mayoría: 55 % de los miembros (al menos 15) y 65 % de la población. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3105","p":"Tratado de la Unión Europea. El Consejo. Una minoría de bloqueo estará compuesta por al menos cuatro miembros del Consejo, a falta de lo cual:","o":["la mayoría cualificada se considerará alcanzada.","se requerirá una nueva votación por unanimidad.","el asunto se remitirá al Consejo Europeo.","la decisión quedará aplazada hasta nueva convocatoria."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la mayoría cualificada se considerará alcanzada</mark></span>El <span class=\"ref-norma\">art. 16.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"a falta de lo cual la mayoría cualificada se considerará alcanzada\"</span>. Sin cuatro miembros no hay minoría de bloqueo y se considera alcanzada la mayoría cualificada. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3106","p":"Tratado de la Unión Europea. El Consejo. El Consejo se reunirá en diferentes formaciones; el Consejo de Asuntos Generales velará por la coherencia de los trabajos de las diferentes formaciones y preparará las reuniones del:","o":["Parlamento Europeo y garantizará su actuación subsiguiente.","Consejo de Asuntos Exteriores y garantizará su coordinación.","Comité de Representantes Permanentes y garantizará su seguimiento.","Consejo Europeo y garantizará su actuación subsiguiente."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Consejo Europeo y garantizará su actuación subsiguiente</mark></span>El <span class=\"ref-norma\">art. 16.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Preparará las reuniones del Consejo Europeo y garantizará su actuación subsiguiente\"</span>. El Consejo de Asuntos Generales prepara las reuniones del Consejo Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3107","p":"Tratado de la Unión Europea. El Consejo. El Consejo de Asuntos Exteriores elaborará la acción exterior de la Unión atendiendo a las líneas estratégicas definidas por el Consejo Europeo y velará por:","o":["la unidad de la acción de la Unión.","la eficacia de la acción de la Unión.","la coherencia de la acción de la Unión.","la continuidad de la acción de la Unión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la coherencia de la acción de la Unión</mark></span>El <span class=\"ref-norma\">art. 16.6 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"velará por la coherencia de la acción de la Unión\"</span>. Vela por la coherencia de la acción de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3108","p":"Tratado de la Unión Europea. El Consejo. Un Comité de Representantes Permanentes de los Gobiernos de los Estados miembros se encargará de:","o":["ejecutar las decisiones del Consejo.","preparar los trabajos del Consejo.","controlar los trabajos del Consejo.","presidir las formaciones del Consejo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">preparar los trabajos del Consejo</mark></span>El <span class=\"ref-norma\">art. 16.7 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"se encargará de preparar los trabajos del Consejo\"</span>. El COREPER prepara los trabajos del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3109","p":"Tratado de la Unión Europea. El Consejo. El Consejo se reunirá en público cuando delibere y vote sobre un proyecto de acto legislativo; con este fin, cada sesión del Consejo se dividirá en dos partes, dedicadas respectivamente a:","o":["las deliberaciones sobre los actos legislativos de la Unión y a las actividades no legislativas.","las deliberaciones sobre los actos legislativos y a las votaciones de los actos no legislativos.","las deliberaciones públicas de la Unión y a las deliberaciones reservadas de los Estados.","los actos legislativos adoptados por el Consejo y a los actos legislativos propuestos por la Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">las deliberaciones sobre los actos legislativos de la Unión y a las actividades no legislativas</mark></span>El <span class=\"ref-norma\">art. 16.8 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"cada sesión del Consejo se dividirá en dos partes, dedicadas respectivamente a las delibe-raciones sobre los actos legislativos de la Unión y a las actividades no legislativas\"</span>. La sesión se divide en parte legislativa (pública) y parte no legislativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3110","p":"Tratado de la Unión Europea. El Consejo. La presidencia de las formaciones del Consejo, con excepción de la de Asuntos Exteriores, será desempeñada por los representantes de los Estados miembros en el Consejo mediante:","o":["un sistema de rotación proporcional.","un sistema de elección por mayoría.","un sistema de designación por el Consejo Europeo.","un sistema de rotación igual."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">un sistema de rotación igual</mark></span>El <span class=\"ref-norma\">art. 16.9 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"mediante un sistema de rotación igual\"</span>. Sistema de rotación igual; la de Asuntos Exteriores la preside el Alto Representante. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 18 — Alto Representante ✱ R9","q":[{"i":"3-26","p":"Tratado de la Unión Europea. El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad: Señale la incorrecta.","o":["Presidirá el Consejo de Asuntos Exteriores.","Será uno de los Vicepresidentes del Consejo Europeo.","Velará por la coherencia de la acción exterior de la Unión.","Todas son correctas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Será uno de los Vicepresidentes del Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 18.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad. El Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. Conforme al artículo 18.4 del TUE, el Alto Representante será uno de los Vicepresidentes de la Comisión, no del Consejo Europeo, además de presidir el Consejo de Asuntos Exteriores y velar por la coherencia de la acción exterior de la Unión."},{"i":"3-168","p":"Tratado de la Unión Europea. El Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad se nombrará por:","o":["El Consejo Europeo por mayoría cualificada, con la aprobación del Presidente de la Comisión.","La Comisión por mayoría cualificada, con la aprobación del Presidente del Consejo Europeo.","El Parlamento Europeo por mayoría cualificada, con la aprobación del Presidente de la Comisión.","La Comisión por mayoría cualificada, con la aprobación del Presidente del Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo Europeo por mayoría cualificada, con la aprobación del Presidente de la Comisión</mark></span>El <span class=\"ref-norma\">art. 18.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad. El Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. El artículo 18.1 del TUE establece que el Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad."},{"i":"3-196","p":"Tratado de la Unión Europea. Disposiciones sobre las Instituciones. ¿Cómo es nombrado el Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad?","o":["La Comisión nombrará por mayoría cualificada.","El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión.","El Parlamento Europeo por unanimidad.","El Consejo Europeo nombrará por unanimidad, con la aprobación del Presidente de la Comisión."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión</mark></span>El <span class=\"ref-norma\">art. 18.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad. El Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. El artículo 18.1 del TUE establece que el Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad."},{"i":"3-281","p":"Tratado de la Unión Europea. En relación al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad, señale la INCORRECTA:","o":["El Alto Representante será uno de los Vicepresidentes de la Comisión.","El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","El Alto Representante presidirá el Consejo de Asuntos Generales.","El Alto Representante estará al frente de la política exterior y de seguridad común de la Unión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">El Alto Representante presidirá el Consejo de Asuntos Generales</mark></span>El <span class=\"ref-norma\">art. 18.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"El Alto Representante presidirá el Consejo de Asuntos Exteriores\"</span>. El artículo 18.3 del TUE dispone que el Alto Representante presidirá el Consejo de Asuntos Exteriores, no el de Asuntos Generales, por lo que esa afirmación resulta incorrecta."},{"i":"3-366","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Consejo. El Consejo, por mayoría simple, podrá pedir a la Comisión que proceda a efectuar todos los estudios que él considere oportunos. Si la Comisión no presenta propuesta alguna, comunicará las razones:","o":["Al Parlamento Europeo.","Al Consejo Europeo.","Al Tribunal de Justicia.","Al Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Al Consejo</mark></span>El <span class=\"ref-norma\">art. 241 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Si la Comisión no presenta propuesta alguna, comunicará las razones al Consejo\"</span>. Debe comunicar las razones al Consejo."},{"i":"3-364","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Consejo Europeo. El Consejo Europeo adoptará por mayoría cualificada una decisión relativa a la presidencia de las formaciones del Consejo, con excepción de:","o":["La de Asuntos Generales.","La de Asuntos Exteriores.","La de Economía y Finanzas.","La de Justicia e Interior."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La de Asuntos Exteriores</mark></span>El <span class=\"ref-norma\">art. 236 del TFUE</span> dispone: <span class=\"ref-concepto\">\"una decisión relativa a la presidencia de las formaciones del Consejo, con excepción de la de Asuntos Exteriores\"</span>. La presidencia de Asuntos Exteriores corresponde al Alto Representante."},{"i":"3-ia-3126","p":"Tratado de la Unión Europea. El Alto Representante. El Alto Representante estará al frente de la política exterior y de seguridad común de la Unión, contribuirá con sus propuestas a elaborarla y la ejecutará como mandatario del Consejo; además:","o":["presidirá el Consejo de Asuntos Generales.","presidirá el Consejo Europeo en asuntos exteriores.","coordinará el Comité de Representantes Permanentes.","presidirá el Consejo de Asuntos Exteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">presidirá el Consejo de Asuntos Exteriores</mark></span>El <span class=\"ref-norma\">art. 18.2 y 3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Alto Representante presidirá el Consejo de Asuntos Exteriores\"</span>. Preside el Consejo de Asuntos Exteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-65","p":"Tratado de la Unión Europea. Los actos legislativos de la Unión, excepto cuando los Tratados dispongan otra cosa, sólo podrán adoptarse a propuesta de:","o":["El Parlamento Europeo.","La Comisión.","El Consejo.","El Consejo Europeo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La Comisión</mark></span>El <span class=\"ref-norma\">art. 17.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los Tratados dispongan otra cosa. Los demás actos se adoptarán a propuesta de la Comisión cuando así lo establezcan los Tratados\"</span>. El artículo 17.2 del TUE establece que los actos legislativos de la Unión sólo podrán adoptarse a propuesta de la Comisión, excepto cuando los Tratados dispongan otra cosa."}]},{"a":"Artículo 19 — Tribunal de Justicia de la Unión Europea ✱ R10","q":[{"i":"3-135","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. El Tribunal de Justicia de la Unión Europea comprenderá:","o":["El Tribunal de Justicia.","El Tribunal General.","Los tribunales especializados.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 256.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Tribunal General será competente para conocer de los recursos que se interpongan contra las resoluciones de los tribunales especializados\"</span>. El artículo 19.1 del TUE dispone que el Tribunal de Justicia de la Unión Europea comprenderá el Tribunal de Justicia, el Tribunal General y los tribunales especializados."},{"i":"3-ia-3128","p":"Tratado de la Unión Europea. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea comprenderá el Tribunal de Justicia, el Tribunal General y:","o":["los tribunales de la Función Pública.","los tribunales especializados.","los tribunales regionales de la Unión.","las salas de apelación."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">los tribunales especializados</mark></span>El <span class=\"ref-norma\">art. 19.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el Tribunal General y los tribunales especializados\"</span>. Comprende el Tribunal de Justicia, el Tribunal General y los tribunales especializados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-396","p":"Tratado de la Unión Europea. Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea comprenderá:","o":["El Tribunal de Justicia, el Tribunal General y los tribunales especializados.","El Tribunal de Justicia, el Tribunal General y el Tribunal de Cuentas.","El Tribunal de Justicia y el Tribunal General, exclusivamente.","El Tribunal de Justicia, el Tribunal de Primera Instancia y los tribunales especializados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Tribunal de Justicia, el Tribunal General y los tribunales especializados</mark></span>El <span class=\"ref-norma\">art. 19.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"comprenderá el Tribunal de Justicia, el Tribunal General y los tribunales especializados\"</span>. Ficha RECUERDA R10. <em style=\"color:var(--texto-gris)\">(ficha RECUERDA R10 del temario)</em>"},{"i":"3-406","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Consejo. Cuando no todos los miembros del Consejo participen en la votación, la mayoría cualificada se definirá como un mínimo del 55 % de los miembros del Consejo que represente a Estados miembros participantes que reúnan como mínimo el 65 % de la población de dichos Estados. Una minoría de bloqueo estará compuesta al menos por el número mínimo de miembros del Consejo que represente:","o":["Más del 45 % de la población de los Estados miembros participantes, más un miembro.","Más del 35 % de la población de la Unión, más dos miembros.","Más del 35 % de la población de los Estados miembros participantes, más un miembro.","Más del 35 % de los Estados miembros participantes, más un miembro."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Más del 35 % de la población de los Estados miembros participantes, más un miembro</mark></span>El <span class=\"ref-norma\">art. 238.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"que represente más del 35 % de la población de los Estados miembros participantes, más un miembro\"</span>. La minoría de bloqueo se calcula sobre la población de los Estados participantes. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-ia-3129","p":"Tratado de la Unión Europea. El Tribunal de Justicia de la Unión Europea. Los Estados miembros establecerán las vías de recurso necesarias para garantizar:","o":["la tutela judicial efectiva en los ámbitos cubiertos por el Derecho de la Unión.","la protección jurisdiccional de los derechos reconocidos por la Carta, en los términos que establezca la propia norma.","el acceso a la justicia en los ámbitos de competencia de la Unión.","la aplicación uniforme del Derecho de la Unión en el territorio."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la tutela judicial efectiva en los ámbitos cubiertos por el Derecho de la Unión</mark></span>El <span class=\"ref-norma\">art. 19.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"garantizar la tutela judicial efectiva en los ámbitos cubiertos por el Derecho de la Unión\"</span>. Garantizan la tutela judicial efectiva en los ámbitos cubiertos por el Derecho de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-191","p":"Tratado de la Unión Europea. El Tribunal General dispondrá:","o":["Un juez por Estado miembro.","Al menos dos jueces por Estado miembro.","Al menos de un juez por Estado miembro.","Dos jueces por Estado miembro."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al menos de un juez por Estado miembro</mark></span>El <span class=\"ref-norma\">art. 19.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El TRIBUNAL GENERAL dispondrá al menos de un juez por Estado miembro\"</span>. Según el art. 19.2 TUE, el Tribunal General dispondrá al menos de un juez por Estado miembro."},{"i":"3-ia-3130","p":"Tratado de la Unión Europea. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia estará compuesto por un juez por Estado miembro y asistido por abogados generales; el Tribunal General dispondrá:","o":["de un juez por Estado miembro exactamente.","de dos jueces por Estado miembro.","de un máximo de un juez por Estado miembro.","al menos de un juez por Estado miembro."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">al menos de un juez por Estado miembro</mark></span>El <span class=\"ref-norma\">art. 19.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El TRIBUNAL GENERAL dispondrá al menos de un juez por Estado miembro\"</span>. El Tribunal General tiene al menos un juez por Estado. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-106","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. ¿Para qué periodo serán nombrados los jueces del Tribunal General?","o":["Cinco años.","Tres años.","Seis años.","Cuatro años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis años</mark></span>El <span class=\"ref-norma\">art. 19.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"Serán nombrados de común acuerdo por los Gobiernos de los Estados miembros para un período de seis años. Los jueces y abogados generales salientes podrán ser nombrados de nuevo\"</span>. Nota: Esta pregunta se repite con la pregunta 6."},{"i":"3-209","p":"Tratado de Funcionamiento de la Unión Europea. ¿Durante qué periodo serán elegidos los jueces del Tribunal de Justicia?","o":["Tres años.","Cinco años.","Seis años.","Siete años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis años</mark></span>El <span class=\"ref-norma\">art. 19.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los jueces y abogados generales del Tribunal de Justicia y los jueces del Tribunal General serán elegidos de entre personalidades que ofrezcan plenas garantías de independencia y que reúnan las condiciones contempladas en los artículos 253 y 254 del Tratado de Funcionamiento de la Unión Europea. Serán nombrados de común acuerdo por los Gobiernos de los Estados miembros para un período de seis años\"</span>. El artículo 253 del TFUE establece que los jueces y abogados generales del Tribunal de Justicia serán designados de común acuerdo por los Gobiernos de los Estados miembros por un período de seis años."},{"i":"3-324","p":"Tratado de Funcionamiento de la Unión Europea. ¿Durante qué periodo serán elegidos los jueces del Tribunal de Justicia?","o":["Tres años.","Cinco años.","Seis años.","Siete años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Seis años</mark></span>El <span class=\"ref-norma\">art. 19.2 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los jueces y abogados generales del Tribunal de Justicia y los jueces del Tribunal General serán elegidos de entre personalidades que ofrezcan plenas garantías de independencia y que reúnan las condiciones contempladas en los artículos 253 y 254 del Tratado de Funcionamiento de la Unión Europea. Serán nombrados de común acuerdo por los Gobiernos de los Estados miembros para un período de seis años\"</span>. El artículo 253 TFUE fija el mandato de los jueces del Tribunal de Justicia en seis años."},{"i":"3-ia-3131","p":"Tratado de la Unión Europea. El Tribunal de Justicia de la Unión Europea. Los jueces y abogados generales del Tribunal de Justicia y los jueces del Tribunal General serán nombrados de común acuerdo por los Gobiernos de los Estados miembros para un período de seis años, y los jueces y abogados generales salientes:","o":["no podrán ser nombrados de nuevo.","podrán ser reelegidos una sola vez.","podrán ser nombrados de nuevo.","serán sustituidos por designación directa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">podrán ser nombrados de nuevo</mark></span>El <span class=\"ref-norma\">art. 19.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los jueces y abogados generales salientes podrán ser nombrados de nuevo\"</span>. Seis años, con posibilidad de renovación. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-397","p":"Tratado de la Unión Europea. Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea se pronunciará, de conformidad con los Tratados, con carácter prejudicial, a petición de los órganos jurisdiccionales nacionales, sobre:","o":["La interpretación del Derecho nacional o sobre la validez de los actos adoptados por las instituciones.","La interpretación de los Tratados, exclusivamente, sin que pueda examinar la validez de los actos.","La validez de los actos adoptados por los Estados miembros y por las instituciones de la Unión.","La interpretación del Derecho de la Unión o sobre la validez de los actos adoptados por las instituciones."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La interpretación del Derecho de la Unión o sobre la validez de los actos adoptados por las instituciones</mark></span>El <span class=\"ref-norma\">art. 19.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"con carácter prejudicial, a petición de los órganos jurisdiccionales nacionales, sobre la interpretación del Derecho de la Unión o sobre la validez de los actos adoptados por las instituciones\"</span>. La cuestión prejudicial versa sobre interpretación del Derecho de la Unión y validez de los actos de las instituciones. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-7","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia de la Unión Europea será competente para pronunciarse, con carácter prejudicial:","o":["Sobre la interpretación de los Tratados.","Sobre la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión.","A y B son correctas.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A y B son correctas</mark></span>El <span class=\"ref-norma\">art. 19.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El TRIBUNAL DE JUSTICIA DE LA UNIÓN EUROPEA se pronunciará, de conformidad con los Tratados: a) \u0007sobre los recursos interpuestos por un Estado miembro, por una institución o por personas físicas o jurídicas; b) \u0007con carácter prejudicial, a petición de los órganos jurisdiccionales nacionales, sobre la interpretación del Derecho de la Unión o sobre la validez de los actos adoptados por las instituciones\"</span>. El artículo 267 del TFUE establece que el Tribunal de Justicia de la Unión Europea será competente para pronunciarse con carácter prejudicial tanto sobre la interpretación de los Tratados (letra a) como sobre la validez e interpretación de los actos adoptados por las instituciones, órganos u organismos de la Unión (letra b)."},{"i":"3-ia-3132","p":"Tratado de la Unión Europea. El Tribunal de Justicia de la Unión Europea. El Tribunal de Justicia de la Unión Europea se pronunciará, con carácter prejudicial, a petición de los órganos jurisdiccionales nacionales, sobre la interpretación del Derecho de la Unión o sobre:","o":["la conformidad de las normas nacionales con el Derecho de la Unión.","la validez de los actos adoptados por las instituciones.","la aplicación del Derecho de la Unión en los Estados miembros.","la legalidad de las decisiones de los tribunales nacionales."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la validez de los actos adoptados por las instituciones</mark></span>El <span class=\"ref-norma\">art. 19.3 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"o sobre la validez de los actos adoptados por las instituciones\"</span>. La cuestión prejudicial versa sobre interpretación del Derecho de la Unión o validez de los actos de las instituciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3630","p":"Tratado de Funcionamiento de la Unión Europea. Jurisdicciones nacionales. Sin perjuicio de las competencias que los Tratados atribuyen al Tribunal de Justicia, los litigios en los que la Unión sea parte:","o":["serán de la competencia exclusiva del Tribunal de Justicia de la Unión Europea.","serán resueltos por el Tribunal General en primera instancia.","quedarán sometidos a las jurisdicciones nacionales previa autorización del Tribunal, salvo que se disponga otra cosa en la normativa aplicable.","no podrán ser, por tal motivo, sustraídos a la competencia de las jurisdicciones nacionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">no podrán ser, por tal motivo, sustraídos a la competencia de las jurisdicciones nacionales</mark></span>El <span class=\"ref-norma\">art. 274 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"los litigios en los que la Unión sea parte no podrán ser, por tal motivo, sustraídos a la competencia de las juris\"</span>. La Unión como parte no sustrae el litigio a las jurisdicciones nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 22 — Intereses y objetivos estratégicos R11","q":[{"i":"3-202","p":"Tratado de la Unión Europea. ¿Quién determinará los intereses y objetivos estratégicos de la Unión?","o":["El Consejo.","El Parlamento Europeo.","La Comisión.","El Consejo Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 26.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa\"</span>. El artículo 22.1 del TUE establece que el Consejo Europeo, basándose en los principios y objetivos del artículo 21, determinará los intereses y objetivos estratégicos de la Unión."},{"i":"3-278","p":"Tratado de la Unión Europea. ¿Quién determinará los intereses y objetivos estratégicos de la Unión?","o":["El Consejo.","El Parlamento Europeo.","La Comisión.","El Consejo Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 26.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo determinará los intereses estratégicos de la Unión, fijará los objetivos y definirá las orientaciones generales de la política exterior y de seguridad común, incluidos los asuntos que tengan repercusiones en el ámbito de la defensa\"</span>. El artículo 22.1 del TUE establece que el Consejo Europeo determinará los intereses y objetivos estratégicos de la Unión."},{"i":"3-ia-3139","p":"Tratado de la Unión Europea. Intereses y objetivos estratégicos. El Consejo Europeo determinará los intereses y objetivos estratégicos de la Unión, pronunciándose por unanimidad, basándose en:","o":["una propuesta de la Comisión.","un dictamen del Parlamento Europeo.","una recomendación del Consejo.","un informe del Alto Representante."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una recomendación del Consejo</mark></span>El <span class=\"ref-norma\">art. 22.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo se pronunciará por unanimidad, basándose en una recomendación del Consejo\"</span>. Unanimidad, sobre la base de una recomendación del Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-18","p":"Tratado de Funcionamiento de la Unión Europea. El Tribunal de Justicia estará asistido por ocho abogados generales. Si el Tribunal de Justicia lo solicitare, el Consejo podrá aumentar el número de abogados generales:","o":["Por mayoría simple.","Por mayoría de 3/5.","Por mayoría absoluta.","Por unanimidad."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Por unanimidad</mark></span>El <span class=\"ref-norma\">art. 252 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Tribunal de Justicia estará asistido por ocho abogados generales. Si el Tribunal de Justicia lo solicitare, el Consejo, por unanimidad, podrá aumentar el número de abogados generales\"</span>. El artículo 252 del TFUE dispone que, si el Tribunal de Justicia lo solicitare, el Consejo, por unanimidad, podrá aumentar el número de abogados generales."},{"i":"3-339","p":"Tratado de la Unión Europea. Política exterior y de seguridad común. Política común de seguridad y defensa. Cualquier Estado miembro que, con posterioridad, desee participar en la cooperación estructurada permanente, notificará su intención:","o":["Al Consejo Europeo y a la Comisión.","Al Parlamento Europeo y al Consejo.","Al Consejo y al Alto Representante.","A la Agencia Europea de Defensa."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Consejo y al Alto Representante</mark></span>El <span class=\"ref-norma\">art. 46 del TUE</span> dispone: <span class=\"ref-concepto\">\"Cualquier Estado miembro que, con posterioridad, desee participar en la cooperación estructurada permanente, notificará su intención al Consejo y al Alto Representante\"</span>. La notificación se dirige al Consejo y al Alto Representante."},{"i":"3-ia-3127","p":"Tratado de la Unión Europea. El Alto Representante. El Alto Representante será uno de los Vicepresidentes de la Comisión y velará por la coherencia de la acción exterior de la Unión; dentro de la Comisión, se encargará de:","o":["las responsabilidades de la Comisión en materia de política comercial y de cooperación al desarrollo, conforme al procedimiento que se establezca reglamentariamente.","la coordinación de las políticas internas con incidencia en el ámbito de la acción exterior.","las responsabilidades que incumben a la misma en el ámbito de las relaciones exteriores y de la coordinación de los demás aspectos de la acción exterior.","la representación de la Comisión ante el Consejo de Asuntos Exteriores y el Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las responsabilidades que incumben a la misma en el ámbito de las relaciones exteriores y de la coordinación de los demás aspectos de la acción exterior</mark></span>El <span class=\"ref-norma\">art. 18.4 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se encargará, dentro de la Comisión, de las responsabilidades que incum\"</span>. Asume las relaciones exteriores y la coordinación de los demás aspectos de la acción exterior. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3140","p":"Tratado de la Unión Europea. Intereses y objetivos estratégicos. El Alto Representante, en el ámbito de la política exterior y de seguridad común, y la Comisión, en los demás ámbitos de la acción exterior, podrán presentar al Consejo:","o":["informes conjuntos.","propuestas conjuntas.","iniciativas separadas.","dictámenes conjuntos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">propuestas conjuntas</mark></span>El <span class=\"ref-norma\">art. 22.2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrán presentar propuestas conjuntas al Consejo\"</span>. Pueden presentar propuestas conjuntas al Consejo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 29 — Enfoque de la Unión R12","q":[{"i":"3-185","p":"Tratado de la Unión Europea. ¿Quién adoptará decisiones que definirán el enfoque de la Unión sobre un asunto concreto de carácter geográfico o temático?","o":["El Consejo Europeo.","La Comisión.","El Parlamento Europeo.","El Consejo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">El Consejo</mark></span>El <span class=\"ref-norma\">art. 29 del TUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo adoptará decisiones que definirán el enfoque de la Unión sobre un asunto concreto de carácter geográfico o temático. Los Estados miembros velarán por la conformidad de sus políticas nacionales con las posiciones de la Unión\"</span>. El artículo 29 del TUE establece que el Consejo adoptará decisiones que definirán el enfoque de la Unión sobre un asunto concreto de carácter geográfico o temático."},{"i":"3-ia-3157","p":"Tratado de la Unión Europea. Posiciones de la Unión. El Consejo adoptará decisiones que definirán el enfoque de la Unión sobre un asunto concreto de carácter geográfico o temático; los Estados miembros:","o":["velarán por la conformidad de sus políticas nacionales con las posiciones de la Unión.","adaptarán su legislación nacional a las posiciones de la Unión en el plazo que fije el Consejo.","se abstendrán de adoptar posiciones nacionales distintas de las de la Unión en cualquier foro.","comunicarán sus políticas nacionales al Alto Representante para su coordinación."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">velarán por la conformidad de sus políticas nacionales con las posiciones de la Unión</mark></span>El <span class=\"ref-norma\">art. 29 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los Estados miembros velarán por la conformidad de sus políticas nacionales con las posiciones de la Unión\"</span>. Velan por que sus políticas nacionales sean conformes con las posiciones de la Unión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 45 TFUE — Trabajadores ✱ R15","q":[{"i":"3-182","p":"Tratado de Funcionamiento de la Unión Europea. La libre circulación supondrá:","o":["La abolición de toda discriminación por razón de la nacionalidad entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y las demás condiciones de trabajo.","La abolición de toda discriminación por razón de sexo entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y las demás condiciones de trabajo.","La abolición de toda discriminación por razón de ideología entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y las demás condiciones de trabajo.","Todas las opciones son correctas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">La abolición de toda discriminación por razón de la nacionalidad entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y las demás condiciones de trabajo</mark></span>El <span class=\"ref-norma\">art. 45.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La libre circulación supondrá la abolición de toda discriminación por razón de la nacionalidad entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y las demás condiciones de trabajo\"</span>. El artículo 45.2 del TFUE establece que la libre circulación de trabajadores supondrá la abolición de toda discriminación por razón de la nacionalidad entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y las demás condiciones de trabajo."},{"i":"3-ia-3239","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de trabajadores. Quedará asegurada la libre circulación de los trabajadores dentro de la Unión, lo que supondrá la abolición de toda discriminación por razón de la nacionalidad entre los trabajadores de los Estados miembros, con respecto al empleo, la retribución y:","o":["las prestaciones de seguridad social.","el acceso a la formación profesional.","las demás condiciones de trabajo.","las condiciones de residencia."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">las demás condiciones de trabajo</mark></span>El <span class=\"ref-norma\">art. 45.1 y 2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con respecto al empleo, la retribución y las demás condi-ciones de trabajo\"</span>. Empleo, retribución y demás condiciones de trabajo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-244","p":"Tratado de Funcionamiento de la Unión Europea. Trabajadores. Sin perjuicio de las limitaciones justificadas por razones de orden público, seguridad y salud públicas, la libre circulación de los trabajadores implicará el derecho: señale la INCORRECTA.","o":["De responder a ofertas efectivas de trabajo.","De residir en uno de los Estados miembros con objeto de ejercer en él un empleo, de conformidad con las disposiciones legales, reglamentarias y administrativas aplicables al empleo de los trabajadores nacionales.","De desplazarse libremente para este fin en el territorio de los Estados miembros.","De permanecer en el territorio de un Estado miembro después de haber ejercido en él un empleo, en las condiciones previstas en los reglamentos establecidos por el Consejo Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De permanecer en el territorio de un Estado miembro después de haber ejercido en él un empleo, en las condiciones previstas en los reglamentos establecidos por el Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 45.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007de permanecer en el territorio de un Estado miembro después de haber ejercido en él un empleo, en las condiciones previstas en los reglamentos establecidos por la Comisión\"</span>. (The conditions for remaining in the territory are set by the Commission through regulations, not the European Council.)"},{"i":"3-ia-3240","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de trabajadores. Sin perjuicio de las limitaciones justificadas por razones de orden público, seguridad y salud públicas, la libre circulación de los trabajadores implicará el derecho de responder a ofertas efectivas de trabajo, desplazarse libremente para este fin, residir en un Estado miembro con objeto de ejercer en él un empleo y:","o":["acceder a las prestaciones por desempleo del Estado de acogida durante tres meses, sin perjuicio de lo dispuesto en otras disposiciones.","permanecer en el territorio de un Estado miembro después de haber ejercido en él un empleo.","reagrupar a los miembros de su familia en el territorio del Estado de acogida.","ejercer una actividad por cuenta propia en el territorio del Estado de acogida."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">permanecer en el territorio de un Estado miembro después de haber ejercido en él un empleo</mark></span>El <span class=\"ref-norma\">art. 45.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"de permanecer en el territorio de un Estado miembro después de haber ejercido en él un em\"</span>. El cuarto derecho es permanecer tras haber ejercido un empleo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-6","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de trabajadores. No se aplicarán las disposiciones relativas a la libre circulación de trabajadores:","o":["Que se desplacen a efectos de trabajo.","De desplazamiento ilimitado para ese fin por cualquier Estado.","A los empleos en la administración pública.","De permanecer en el territorio de un Estado miembro después de haber ejercido en él un empleo, en las condiciones previstas en los reglamentos establecidos por la Comisión."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">A los empleos en la administración pública</mark></span>A, B y D son (o deforman) derechos que SÍ implica la libre circulación (art. 45.3). Según el <span class=\"ref-norma\">art. 45.4 del TFUE</span>: <span class=\"ref-concepto\">\"Las disposiciones del presente artículo no serán aplicables a los empleos en la administración pública.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3241","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de trabajadores. Las disposiciones sobre libre circulación de los trabajadores no serán aplicables:","o":["a los empleos en la administración pública.","a los empleos en las fuerzas y cuerpos de seguridad.","a los empleos en el sector de la defensa.","a los empleos de carácter temporal."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">a los empleos en la administración pública</mark></span>El <span class=\"ref-norma\">art. 45.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Las disposiciones del presente artículo no serán aplicables a los empleos en la administración pública\"</span>. Se excluyen los empleos en la administración pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 47 TFUE — Trabajadores jóvenes","q":[{"i":"3-340","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Trabajadores. Los Estados miembros facilitarán, en el marco de un programa común, el intercambio de:","o":["Trabajadores cualificados.","Trabajadores jóvenes.","Estudiantes universitarios.","Funcionarios públicos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Trabajadores jóvenes</mark></span>El <span class=\"ref-norma\">art. 47 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Los Estados miembros facilitarán, en el marco de un programa común, el intercambio de trabajadores jóvenes\"</span>. Programa común de intercambio de trabajadores jóvenes."},{"i":"3-ia-3243","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de trabajadores. Los Estados miembros facilitarán, en el marco de un programa común:","o":["el intercambio de estudiantes universitarios.","la formación de trabajadores migrantes.","el intercambio de trabajadores jóvenes.","la movilidad de investigadores y científicos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">el intercambio de trabajadores jóvenes</mark></span>El <span class=\"ref-norma\">art. 47 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los Estados miembros facilitarán, en el marco de un programa común, el intercambio de trabajadores jóvenes\"</span>. Programa común de intercambio de trabajadores jóvenes. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 67 a 70 TFUE — Disposiciones generales ✱ R17","q":[{"i":"3-ia-3321","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. La Unión constituye un espacio de libertad, seguridad y justicia dentro del respeto:","o":["de los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos de los Estados miembros.","de los derechos fundamentales y de las competencias exclusivas de los Estados miembros.","de los principios del Estado de Derecho y de la soberanía de los Estados miembros.","de las libertades fundamentales y de las tradiciones constitucionales de los Estados miembros, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 67.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"dentro del respeto de los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos de los Estados miembros\"</span>. Respeto de los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-402","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. La Unión constituye un espacio de libertad, seguridad y justicia dentro del respeto de:","o":["Los derechos humanos y de los distintos sistemas y tradiciones jurídicos de los Estados miembros.","Los derechos fundamentales y de las distintas tradiciones constitucionales de los Estados miembros.","Los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos de los Estados miembros.","Los derechos fundamentales y del sistema jurídico común de los Estados miembros."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 67.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"dentro del respeto de los derechos fundamentales y de los distintos sistemas y tradiciones jurídicos de los Estados miembros\"</span>. La fórmula completa incluye derechos fundamentales y sistemas y tradiciones jurídicos de los Estados. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-347","p":"Tratado de Funcionamiento de la Unión Europea. Libre circulación de personas, servicios y capitales. Capital y pagos. En el marco de las disposiciones del capítulo sobre capital y pagos, quedan prohibidas todas las restricciones a los movimientos de capitales:","o":["Entre Estados miembros, pero no con terceros países.","Entre Estados miembros y terceros países, salvo los destinados a inversiones directas.","Entre Estados miembros y entre Estados miembros y terceros países.","Superiores a un determinado importe."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Entre Estados miembros y entre Estados miembros y terceros países</mark></span>El <span class=\"ref-norma\">art. 63 del TFUE</span> dispone: <span class=\"ref-concepto\">\"quedan prohibidas todas las restricciones a los movimientos de capitales entre Estados miembros y entre Estados miembros y terceros países\"</span>. La prohibición alcanza también a los movimientos con terceros países."},{"i":"3-ia-3322","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. La Unión garantizará la ausencia de controles de las personas en las fronteras interiores y desarrollará una política común de asilo, inmigración y control de las fronteras exteriores basada en la solidaridad entre Estados miembros y equitativa respecto de los nacionales de terceros países; a efectos del título, los apátridas:","o":["se asimilarán a los nacionales de los Estados miembros.","recibirán un trato específico según la legislación de cada Estado.","quedarán excluidos del ámbito de aplicación del título.","se asimilarán a los nacionales de terceros países."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">se asimilarán a los nacionales de terceros países</mark></span>El <span class=\"ref-norma\">art. 67.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"los apátridas se asimilarán a los nacionales de terceros países\"</span>. Los apátridas se asimilan a los nacionales de terceros países. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-403","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. La Unión se esforzará por garantizar un nivel elevado de seguridad mediante medidas de prevención de la delincuencia, el racismo y la xenofobia y de lucha en contra de ellos, medidas de coordinación y cooperación entre autoridades policiales y judiciales y otras autoridades competentes, así como mediante el reconocimiento mutuo de las resoluciones judiciales en materia penal y, si es necesario, mediante:","o":["La armonización de los procedimientos penales.","La aproximación de las legislaciones penales.","La unificación de los códigos penales.","La creación de un espacio judicial común."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La aproximación de las legislaciones penales</mark></span>El <span class=\"ref-norma\">art. 67.3 del TFUE</span> dispone: <span class=\"ref-concepto\">\"si es necesario, mediante la aproximación de las legislaciones penales\"</span>. La aproximación de legislaciones penales solo «si es necesario». <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-129","p":"Tratado de Funcionamiento de la Unión Europea. La Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia:","o":["Civil.","Administrativa.","Laboral.","Militar."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Civil</mark></span>El <span class=\"ref-norma\">art. 67.4 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil\"</span>. El artículo 67.4 del TUE establece que la Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil."},{"i":"3-183","p":"Tratado de Funcionamiento de la Unión Europea. La Unión facilitará la tutela judicial, garantizando en especial el principio:","o":["De reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil y mercantil.","De reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil.","De minimis non pro.","De proporcionalidad."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">De reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil</mark></span>El <span class=\"ref-norma\">art. 67.4 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil\"</span>. El artículo 67.4 del TFUE dispone que \"la Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil\", sin mencionar la materia mercantil."},{"i":"3-220","p":"Tratado de Funcionamiento de la Unión Europea. La Unión facilitará la tutela judicial, garantizando en especial el principio de:","o":["Legalidad.","Subsidiariedad.","Proporcionalidad.","Reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil</mark></span>El <span class=\"ref-norma\">art. 67.4 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil\"</span>. El artículo 67.4 del TUE establece que la Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil."},{"i":"3-ia-3324","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. La Unión facilitará la tutela judicial, garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia:","o":["penal.","civil.","mercantil.","administrativa."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">civil</mark></span>El <span class=\"ref-norma\">art. 67.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"garantizando en especial el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales en materia civil\"</span>. El apartado 4 se refiere a la materia civil; el apartado 3 a la penal. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-11","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. ¿Quién definirá las orientaciones estratégicas de la programación legislativa y operativa en el espacio de libertad, seguridad y justicia?","o":["El Consejo Europeo.","El Parlamento Europeo.","El Consejo.","La Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 68 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo definirá las orientaciones estratégicas de la programación legislativa y operativa en el espacio de libertad, seguridad y justicia\"</span>. El artículo 68 del TFUE atribuye al Consejo Europeo la definición de las orientaciones estratégicas de la programación legislativa y operativa en el espacio de libertad, seguridad y justicia."},{"i":"3-ia-3325","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Definirá las orientaciones estratégicas de la programación legislativa y operativa en el espacio de libertad, seguridad y justicia:","o":["el Consejo Europeo.","el Consejo.","la Comisión.","el Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">el Consejo Europeo</mark></span>El <span class=\"ref-norma\">art. 68 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo Europeo definirá las orientaciones estratégicas de la programación legislativa y operativa en el espacio de libertad, seguridad y justicia\"</span>. Las orientaciones estratégicas las define el Consejo Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-350","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. En relación con las propuestas e iniciativas legislativas presentadas en el marco de la cooperación judicial en materia penal y de la cooperación policial, velarán por que se respete el principio de subsidiariedad:","o":["El Consejo Europeo.","La Comisión.","El Tribunal de Justicia de la Unión Europea.","Los Parlamentos nacionales."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Los Parlamentos nacionales</mark></span>El <span class=\"ref-norma\">art. 69 del TFUE</span> dispone: <span class=\"ref-concepto\">\"los Parlamentos nacionales velarán por que se respete el principio de subsidiariedad, de conformidad con el Protocolo\"</span>. El control de subsidiariedad corresponde a los Parlamentos nacionales."},{"i":"3-351","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. El Consejo podrá adoptar, a propuesta de la Comisión, medidas que establezcan los procedimientos para efectuar una evaluación objetiva e imparcial de la aplicación de las políticas del espacio de libertad, seguridad y justicia. Se informará del contenido y los resultados de esta evaluación:","o":["Al Consejo Europeo y a la Comisión Europea, conjuntamente.","Al Tribunal de Justicia y al Comité de las Regiones.","Al Parlamento Europeo y a los Parlamentos nacionales.","Únicamente al Parlamento Europeo y al Consejo Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Al Parlamento Europeo y a los Parlamentos nacionales</mark></span>El <span class=\"ref-norma\">art. 70 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Se informará al Parlamento Europeo y a los Parlamentos nacionales del contenido y los resultados de esta evaluación\"</span>. Se informa al Parlamento Europeo y a los Parlamentos nacionales."},{"i":"3-ia-3327","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. El Consejo podrá adoptar, a propuesta de la Comisión, medidas que establezcan los procedimientos que seguirán los Estados miembros para efectuar, en colaboración con la Comisión, una evaluación objetiva e imparcial de la aplicación de las políticas del título, en particular con objeto de favorecer la plena aplicación del principio de reconocimiento mutuo; se informará del contenido y los resultados de esta evaluación:","o":["al Consejo Europeo y a la Comisión.","al Parlamento Europeo y al Consejo Europeo.","al Parlamento Europeo y a los Parlamentos nacionales.","a los Parlamentos nacionales y al Comité de las Regiones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">al Parlamento Europeo y a los Parlamentos nacionales</mark></span>El <span class=\"ref-norma\">art. 70 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se informará al Parlamento Europeo y a los Parlamentos nacionales del contenido y los resultados de esta evaluación\"</span>. Se informa al Parlamento Europeo y a los Parlamentos nacionales. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 77 TFUE — Controles en las fronteras","q":[{"i":"3-404","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Controles en las fronteras. La Unión desarrollará una política que tendrá por objetivo garantizar la ausencia total de controles de las personas, sea cual sea su nacionalidad, cuando crucen:","o":["Las fronteras interiores.","Las fronteras exteriores.","Las fronteras de los Estados que apliquen el acervo de Schengen.","Las fronteras de cualquier Estado miembro."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Las fronteras interiores</mark></span>El <span class=\"ref-norma\">art. 77.1.a del TFUE</span> dispone: <span class=\"ref-concepto\">\"garantizar la ausencia total de controles de las personas, sea cual sea su nacionalidad, cuando crucen las fronteras interiores\"</span>. Ausencia total de controles en las fronteras interiores. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-123","p":"Tratado de Funcionamiento de la Unión Europea. Políticas sobre controles en las fronteras, asilo e inmigración. La Unión desarrollará una política que tendrá por objetivo:","o":["Garantizar la ausencia total de controles de las personas, sea cual sea su nacionalidad, cuando cruzan las fronteras interiores.","Garantizar los controles de las personas y la vigilancia eficaz en el cruce de las fronteras exteriores.","Instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 77.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"garantizar la ausencia total de controles de las personas, sea cual sea su nacionalidad, cuando crucen las fronteras interiores; b) garantizar los controles de las personas y la vigilancia eficaz en el cruce de las fronteras exteriores; c) instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores\"</span>. El artículo 77.1 del TFUE recoge como objetivos de la política de la Unión garantizar la ausencia total de controles en las fronteras interiores, garantizar los controles y la vigilancia en las fronteras exteriores, e instaurar progresivamente un sistema integrado de gestión de dichas fronteras."},{"i":"3-405","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Controles en las fronteras. La Unión desarrollará una política que tendrá por objetivo instaurar progresivamente un sistema integrado de gestión de:","o":["Las fronteras interiores.","Los flujos migratorios.","Los controles policiales.","Las fronteras exteriores."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Las fronteras exteriores</mark></span>El <span class=\"ref-norma\">art. 77.1.c del TFUE</span> dispone: <span class=\"ref-concepto\">\"instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores\"</span>. Sistema integrado de gestión de las fronteras exteriores. <em style=\"color:var(--texto-gris)\">(círculo EXOF / sello PREGUNTA EXAMEN del temario)</em>"},{"i":"3-27","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Políticas sobre controles en las fronteras, asilo e inmigración. La Unión desarrollará una política que tendrá por objetivo: Señale la correcta.","o":["Garantizar la ausencia total de controles de las personas nacionales en los Estados miembros, cuando se crucen las fronteras interiores.","Garantizar los controles de las personas de terceros países y la vigilancia eficaz en el cruce de las fronteras exteriores.","Instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores</mark></span>A es falsa porque restringe a «personas nacionales» (el texto dice «sea cual sea su nacionalidad») y B porque restringe a «personas de terceros países». Solo C es literal. Según el <span class=\"ref-norma\">art. 77.1 del TFUE</span>: <span class=\"ref-concepto\">\"a) garantizar la ausencia total de controles de las personas, sea cual sea su nacionalidad, cuando crucen las fronteras interiores; b) garantizar los controles de las personas y la vigilancia eficaz en el cruce de las fronteras exteriores; c) instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3335","p":"Tratado de Funcionamiento de la Unión Europea. Controles en las fronteras. La Unión desarrollará una política que tendrá por objetivo garantizar la ausencia total de controles de las personas, sea cual sea su nacionalidad, cuando crucen las fronteras interiores, garantizar los controles de las personas y la vigilancia eficaz en el cruce de las fronteras exteriores e:","o":["instaurar progresivamente un cuerpo europeo de guardias de fronteras y costas.","instaurar progresivamente un sistema común de visados de corta y larga duración.","instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores.","instaurar progresivamente un registro europeo de entradas y salidas de nacionales de terceros países."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores</mark></span>El <span class=\"ref-norma\">art. 77.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"instaurar progresivamente un sistema integrado de gestión de las fronteras exteriores\"</span>. Tercer objetivo: sistema integrado de gestión de las fronteras exteriores. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-19","p":"Derecho de la Unión Europea. Tratado de Funcionamiento de la UE. ¿Qué institución adoptará medidas relacionadas con la política común de visados y otros permisos de residencia de corta duración?","o":["El Parlamento Europeo y el Consejo.","El Parlamento Europeo y la Comisión.","La Comisión y el Consejo.","El Consejo Europeo y la Comisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">El Parlamento Europeo y el Consejo</mark></span>El <span class=\"ref-norma\">art. 77.2 del TFUE</span> dispone: <span class=\"ref-concepto\">\"A efectos del apartado 1, el Parlamento Europeo y el Consejo adoptarán, con arreglo al procedimiento legislativo ordinario, medidas relativas a: a) la política común de visados y otros permisos de residencia de corta duración\"</span>. El artículo 77.2.a) del TFUE atribuye al Parlamento Europeo y al Consejo, con arreglo al procedimiento legislativo ordinario, la adopción de medidas relativas a la política común de visados y otros permisos de residencia de corta duración."},{"i":"3-ia-3152","p":"Tratado de la Unión Europea. Acción operativa. Cuando una situación internacional exija una acción operativa de la Unión, el Consejo adoptará las decisiones necesarias, que fijarán los objetivos, el alcance, los medios que haya que facilitar a la Unión, las condiciones de su ejecución y, en caso necesario:","o":["su financiación.","su duración.","su revisión periódica.","su ámbito territorial."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">su duración</mark></span>El <span class=\"ref-norma\">art. 28.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"las condiciones de su ejecución y, en caso necesario, su duración\"</span>. Se fija, si es necesario, su duración. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3413","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. Cuando la aproximación de las disposiciones legales y reglamentarias de los Estados miembros en materia penal resulte imprescindible para garantizar la ejecución eficaz de una política de la Unión en un ámbito que haya sido objeto de medidas de armonización, se podrá establecer mediante directivas normas mínimas relativas a la definición de las infracciones penales y de las sanciones; dichas directivas se adoptarán:","o":["con arreglo a un procedimiento legislativo ordinario o especial idéntico al empleado para la adopción de las medidas de armonización en cuestión.","con arreglo al procedimiento legislativo especial, por unanimidad del Consejo y previa aprobación del Parlamento Europeo, en los términos que establezca la propia norma.","con arreglo al procedimiento legislativo ordinario, por mayoría cualificada del Consejo en todo caso.","con arreglo al procedimiento que determine el Consejo Europeo en cada caso por unanimidad."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">con arreglo a un procedimiento legislativo ordinario o especial idéntico al empleado para la adopción de las medidas de armonización en cuestión</mark></span>El <span class=\"ref-norma\">art. 83.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Dichas directivas se adoptarán con arreglo a un procedimiento legislativo ordinario o es-pecial idéntico al empleado para la adopción de las medidas de armonización en cuestión\"</span>. Teoría de la accesoriedad: mismo procedimiento que el de las medidas de armonización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3337","p":"Tratado de Funcionamiento de la Unión Europea. Controles en las fronteras. Si resulta necesaria una acción de la Unión para facilitar el ejercicio del derecho de los ciudadanos a circular y residir libremente, y a menos que los Tratados hayan previsto poderes de actuación a tal efecto, el Consejo podrá establecer disposiciones relativas a los pasaportes, documentos de identidad, permisos de residencia o cualquier otro documento asimilado, con arreglo a un procedimiento legislativo especial:","o":["por unanimidad, previa consulta al Parlamento Europeo.","por mayoría cualificada, previa consulta al Parlamento Europeo.","por unanimidad, previa aprobación del Parlamento Europeo.","por mayoría cualificada, previa aprobación del Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">por unanimidad, previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 77.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará por unanimidad, previa consulta al Parlamento Europeo\"</span>. Procedimiento legislativo especial: unanimidad y consulta. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 78 a 80 TFUE — Asilo e inmigración ✱ R18","q":[{"i":"3-136","p":"Tratado de Funcionamiento de la Unión Europea. Políticas sobre controles en las fronteras, asilo e inmigración. La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del principio:","o":["De cooperación.","De no discriminación.","De legalidad.","De no devolución."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">De no devolución</mark></span>El <span class=\"ref-norma\">art. 78.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del principio de no devolución\"</span>. El artículo 78.1 del TFUE establece que la Unión desarrollará una política común en materia de asilo destinada a garantizar el respeto del principio de no devolución."},{"i":"3-160","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Políticas sobre controles en las fronteras, asilo e inmigración. La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del:","o":["Principio de igualdad.","Principio de solidaridad.","Principio de no devolución.","Principio de legalidad."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Principio de no devolución</mark></span>El <span class=\"ref-norma\">art. 78.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del principio de no devolución\"</span>. El artículo 78.1 del TFUE establece que la Unión desarrollará una política común de asilo destinada a garantizar el respeto del principio de no devolución."},{"i":"3-247","p":"Tratado de Funcionamiento de la Unión Europea. Políticas sobre controles en las fronteras, asilo e inmigración. La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del principio de:","o":["Proporcionalidad.","Subsidiariedad.","No devolución.","Atribución."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">No devolución</mark></span>El <span class=\"ref-norma\">art. 78.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del principio de no devolución\"</span>. El artículo 78.1 del TFUE establece que la Unión desarrollará una política común en materia de asilo destinada a garantizar el respeto del principio de no devolución."},{"i":"3-ia-3339","p":"Tratado de Funcionamiento de la Unión Europea. Asilo. La Unión desarrollará una política común en materia de asilo, protección subsidiaria y protección temporal destinada a ofrecer un estatuto apropiado a todo nacional de un tercer país que necesite protección internacional y a garantizar el respeto del principio de no devolución; esta política deberá ajustarse a:","o":["la Convención de Ginebra de 28 de julio de 1951 y al Convenio Europeo de Derechos Humanos de 1950, conforme al procedimiento que se establezca reglamentariamente.","la Declaración Universal de Derechos Humanos de 1948 y al Protocolo de 31 de enero de 1967.","la Convención de Ginebra de 28 de julio de 1951 y al Protocolo de 31 de enero de 1967 sobre el Estatuto de los Refugiados.","la Convención de Ginebra de 12 de agosto de 1949 y al Protocolo de 31 de enero de 1967."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la Convención de Ginebra de 28 de julio de 1951 y al Protocolo de 31 de enero de 1967 sobre el Estatuto de los Refugiados</mark></span>El <span class=\"ref-norma\">art. 78.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Esta política deberá ajustarse a la Convención de Ginebra de 28 de julio de 1951 y al Protocolo de 31 de enero de 1967 sobre el Estatuto de los Refugiados\"</span>. Convención de Ginebra de 1951 y Protocolo de 1967. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3340","p":"Tratado de Funcionamiento de la Unión Europea. Asilo. El sistema europeo común de asilo incluirá un estatuto uniforme de asilo para nacionales de terceros países, válido en toda la Unión, un estatuto uniforme de protección subsidiaria y:","o":["un sistema común de reparto obligatorio de los solicitantes de asilo entre los Estados miembros.","un sistema común para la protección temporal de las personas desplazadas, en caso de afluencia masiva.","un sistema común de acogida e integración de las personas beneficiarias de protección internacional, sin perjuicio de lo dispuesto en otras disposiciones.","un sistema común de retorno de los solicitantes de asilo cuya solicitud haya sido denegada."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">un sistema común para la protección temporal de las personas desplazadas, en caso de afluencia masiva</mark></span>El <span class=\"ref-norma\">art. 78.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"un sistema común para la protección temporal de las personas desplazadas, en caso de afluen-cia masiva\"</span>. Incluye un sistema común de protección temporal en caso de afluencia masiva. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3342","p":"Tratado de Funcionamiento de la Unión Europea. Asilo. Si uno o varios Estados miembros se enfrentan a una situación de emergencia caracterizada por la afluencia repentina de nacionales de terceros países, el Consejo podrá adoptar, a propuesta de la Comisión, medidas provisionales en beneficio de los Estados miembros afectados, pronunciándose:","o":["previa aprobación del Parlamento Europeo.","por unanimidad.","previa consulta al Consejo Europeo.","previa consulta al Parlamento Europeo."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">previa consulta al Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 78.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Consejo se pronunciará previa consulta al Parlamento Europeo\"</span>. Medidas provisionales: propuesta de la Comisión y consulta al Parlamento. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-171","p":"Tratado de Funcionamiento de la Unión Europea. La Unión desarrollará una política común de inmigración destinada a garantizar:","o":["Una gestión eficaz de los flujos migratorios.","Un trato equitativo de los nacionales de terceros países que residan legalmente en los Estados miembros.","Una prevención de la inmigración ilegal y de la trata de seres humanos.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 79.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"La Unión desarrollará una política común de inmigración destinada a garantizar, en todo momento, una gestión eficaz de los flujos migratorios, un trato equitativo de los nacionales de terceros países que residan legalmente en los Estados miembros, así como una prevención de la inmigración ilegal y de la trata de seres humanos y una lucha reforzada contra ambas\"</span>. El artículo 79.1 del TFUE establece que la Unión desarrollará una política común de inmigración destinada a garantizar una gestión eficaz de los flujos migratorios, un trato equitativo de los nacionales de terceros países que residan legalmente, y la prevención y lucha contra la inmigración ilegal y la trata de seres humanos."},{"i":"3-ia-3206","p":"Tratado de la Unión Europea. Misiones diplomáticas y consulares. Las misiones diplomáticas y consulares contribuirán a la aplicación del derecho de los ciudadanos de la Unión a gozar de:","o":["asistencia jurídica en el territorio de terceros países.","representación diplomática en los Estados miembros.","libre circulación en el territorio de terceros países.","protección en el territorio de terceros países."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">protección en el territorio de terceros países</mark></span>El <span class=\"ref-norma\">art. 35 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"del derecho de los ciudadanos de la Unión a gozar de protección en el territorio\"</span>. Contribuyen a la protección diplomática y consular de los ciudadanos de la Unión en terceros países. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3229","p":"Tratado de la Unión Europea. Misiones de la política común de seguridad y defensa. Todas estas misiones podrán contribuir a la lucha contra el terrorismo, entre otras cosas:","o":["mediante el apoyo prestado a terceros países para combatirlo en su territorio.","mediante el intercambio de información entre los servicios de inteligencia.","mediante la coordinación de las acciones policiales de los Estados miembros.","mediante la participación en operaciones de las fuerzas de seguridad nacionales."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">mediante el apoyo prestado a terceros países para combatirlo en su territorio</mark></span>El <span class=\"ref-norma\">art. 43.1 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"entre otras cosas mediante el apoyo prestado a terceros países para combatirlo en su territorio\"</span>. Mediante el apoyo a terceros países en su propio territorio. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3341","p":"Tratado de Funcionamiento de la Unión Europea. Asilo. El sistema europeo común de asilo incluirá también procedimientos comunes para conceder o retirar el estatuto uniforme de asilo o de protección subsidiaria, criterios y mecanismos para determinar el Estado miembro responsable de examinar una solicitud, normas relativas a las condiciones de acogida y:","o":["la asociación y la cooperación con terceros países para gestionar los flujos de personas que solicitan asilo o una protección subsidiaria o temporal.","la distribución de los solicitantes de asilo entre los Estados miembros conforme a cuotas.","la creación de una agencia europea con competencias para resolver las solicitudes de asilo, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","el establecimiento de centros de acogida de solicitantes de asilo en terceros países."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la asociación y la cooperación con terceros países para gestionar los flujos de personas que solicitan asilo o una protección subsidiaria o temporal</mark></span>El <span class=\"ref-norma\">art. 78.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la asociación y la cooperación con terceros países para gestionar los flujos de personas que\"</span>. Última medida: asociación y cooperación con terceros países. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3343","p":"Tratado de Funcionamiento de la Unión Europea. Inmigración. La Unión desarrollará una política común de inmigración destinada a garantizar, en todo momento, una gestión eficaz de los flujos migratorios, un trato equitativo de los nacionales de terceros países que residan legalmente en los Estados miembros, así como una prevención de la inmigración ilegal y de la trata de seres humanos y:","o":["una lucha coordinada contra ambas.","una cooperación policial contra ambas.","una lucha reforzada contra ambas.","una persecución penal de ambas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">una lucha reforzada contra ambas</mark></span>El <span class=\"ref-norma\">art. 79.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"así como una prevención de la inmigración ilegal y de la trata de seres humanos y una lucha reforzada contra ambas\"</span>. Prevención y lucha reforzada contra la inmigración ilegal y la trata. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3344","p":"Tratado de Funcionamiento de la Unión Europea. Inmigración. El Parlamento Europeo y el Consejo adoptarán, con arreglo al procedimiento legislativo ordinario, medidas en los ámbitos de las condiciones de entrada y residencia y las normas sobre visados y permisos de residencia de larga duración, incluidos los destinados a la reagrupación familiar, la definición de los derechos de los nacionales de terceros países que residan legalmente en un Estado miembro, la inmigración y residencia ilegales y:","o":["la lucha contra el tráfico ilícito de migrantes y las redes de delincuencia organizada.","la lucha contra la trata de seres humanos, en particular de mujeres y niños.","la protección de las víctimas de la trata de seres humanos y de la explotación laboral.","la cooperación con terceros países en materia de control de las fronteras exteriores."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">la lucha contra la trata de seres humanos, en particular de mujeres y niños</mark></span>El <span class=\"ref-norma\">art. 79.2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la lucha contra la trata de seres humanos, en particular de mujeres y niños\"</span>. Cuarto ámbito: lucha contra la trata, en particular de mujeres y niños. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-410","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia: política de inmigración. La Unión podrá celebrar con terceros países acuerdos para la readmisión, en sus países de origen o de procedencia, de nacionales de terceros países que:","o":["Hayan solicitado protección internacional en el territorio de uno de los Estados miembros y les haya sido denegada.","No cumplan o que hayan dejado de cumplir las condiciones de entrada, presencia o residencia en el territorio de uno de los Estados miembros.","No cumplan las condiciones de entrada en el territorio de la Unión, con exclusión de los que hayan dejado de cumplir las de residencia, sin perjuicio de lo que establezcan los tratados internacionales.","Hayan cometido un delito grave en el territorio de uno de los Estados miembros y sean expulsados por resolución judicial firme."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">No cumplan o que hayan dejado de cumplir las condiciones de entrada, presencia o residencia en el territorio de uno de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 79.3 de la TFUE</span> dispone: <span class=\"ref-concepto\">\"3. La Unión podrá celebrar con terceros países acuerdos para la readmisión, en sus países de origen o de procedencia, de nacionales de terceros países que no cumplan o que hayan dejado de cumplir las condiciones de entrada, presencia o residencia en el territorio de uno de los Estados miembros.\"</span>"},{"i":"3-ia-3345","p":"Tratado de Funcionamiento de la Unión Europea. Inmigración. La Unión podrá celebrar con terceros países acuerdos para la readmisión, en sus países de origen o de procedencia, de nacionales de terceros países que:","o":["no cumplan o que hayan dejado de cumplir las condiciones de entrada, presencia o residencia en el territorio de uno de los Estados miembros.","hayan sido objeto de una decisión de expulsión por razones de orden público o de seguridad nacional, en los términos que establezca la propia norma.","hayan cometido infracciones penales graves en el territorio de uno de los Estados miembros.","hayan solicitado asilo en uno de los Estados miembros y cuya solicitud haya sido denegada."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">no cumplan o que hayan dejado de cumplir las condiciones de entrada, presencia o residencia en el territorio de uno de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 79.3 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"que no cumplan o que hayan dejado de cumplir las condiciones de entrada, presencia o residencia en el territorio de uno de los Estados miembros\"</span>. Acuerdos de readmisión: quienes no cumplan o dejen de cumplir las condiciones de entrada, presencia o residencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-357","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Fronteras, asilo e inmigración. Las políticas de la Unión sobre fronteras, asilo e inmigración y su ejecución se regirán por el principio de solidaridad y de reparto equitativo de la responsabilidad entre los Estados miembros, también en el aspecto:","o":["Financiero.","Político y diplomático.","Operativo y logístico.","Jurídico y administrativo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Financiero</mark></span>El <span class=\"ref-norma\">art. 80 del TFUE</span> dispone: <span class=\"ref-concepto\">\"también en el aspecto financiero\"</span>. La solidaridad alcanza también al aspecto financiero."},{"i":"3-ia-3348","p":"Tratado de Funcionamiento de la Unión Europea. Solidaridad en asilo, inmigración y fronteras. Las políticas de la Unión sobre controles en las fronteras, asilo e inmigración y su ejecución se regirán por el principio de solidaridad y de reparto equitativo de la responsabilidad entre los Estados miembros:","o":["también en el aspecto operativo.","también en el aspecto financiero.","también en el aspecto jurídico.","también en el aspecto institucional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">también en el aspecto financiero</mark></span>El <span class=\"ref-norma\">art. 80 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"por el principio de solidaridad y de reparto equitativo de la responsabilidad entre los Estados miembros, también en el as-pecto financiero\"</span>. Solidaridad y reparto equitativo, también en el aspecto financiero. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 84 TFUE — Prevención de la delincuencia ✱ R19","q":[{"i":"3-355","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Disposiciones generales. Para la prevención y lucha contra el terrorismo, el Parlamento Europeo y el Consejo definirán, con arreglo al procedimiento legislativo ordinario, un marco de medidas administrativas sobre movimiento de capitales y pagos, tales como la inmovilización de fondos. Lo harán mediante:","o":["Directivas.","Decisiones.","Reglamentos.","Recomendaciones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Reglamentos</mark></span>El <span class=\"ref-norma\">art. 75 del TFUE</span> dispone: <span class=\"ref-concepto\">\"definirán mediante reglamentos, con arreglo al procedimiento legislativo ordinario, un marco de medidas administrativas sobre movimiento de capitales y pagos\"</span>. El marco se define mediante reglamentos."},{"i":"3-358","p":"Tratado de Funcionamiento de la Unión Europea. Espacio de libertad, seguridad y justicia. Cooperación judicial en materia penal. El Parlamento Europeo y el Consejo podrán establecer, con arreglo al procedimiento legislativo ordinario, medidas que impulsen y apoyen la actuación de los Estados miembros en el ámbito de la prevención de la delincuencia, con exclusión de toda:","o":["Cooperación entre las autoridades judiciales de los Estados miembros en materia penal.","Intervención de Europol y Eurojust en las investigaciones de los Estados miembros.","Aproximación de las sanciones penales de los Estados miembros en todos los casos.","Armonización de las disposiciones legales y reglamentarias de los Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Armonización de las disposiciones legales y reglamentarias de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 84 del TFUE</span> dispone: <span class=\"ref-concepto\">\"con exclusión de toda armonización de las disposiciones legales y reglamentarias de los Estados miembros\"</span>. Se excluye toda armonización."},{"i":"3-360","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. El Parlamento Europeo. El Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, establecerán el estatuto de los partidos políticos a escala europea y, en particular, las normas relativas a su financiación, mediante:","o":["Directivas.","Reglamentos.","Decisiones.","Recomendaciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Reglamentos</mark></span>El <span class=\"ref-norma\">art. 224 del TFUE</span> dispone: <span class=\"ref-concepto\">\"establecerán mediante reglamentos el estatuto de los partidos políticos a escala europea\"</span>. Se establece mediante reglamentos."},{"i":"3-ia-3301","p":"Tratado de Funcionamiento de la Unión Europea. Derecho de establecimiento. A fin de facilitar el acceso a las actividades no asalariadas y su ejercicio, el Parlamento Europeo y el Consejo, con arreglo al procedimiento legislativo ordinario, adoptarán directivas para el reconocimiento mutuo de diplomas, certificados y otros títulos, así como para:","o":["la coordinación de las disposiciones legales, reglamentarias y administrativas de los Estados miembros relativas al acceso a las actividades por cuenta propia y a su ejercicio.","la armonización de los sistemas de formación y de cualificación profesional de los Estados miembros.","la equiparación de las condiciones de ejercicio de las profesiones reguladas en el conjunto de la Unión, en los términos que establezca la propia norma, salvo que se disponga otra cosa en la normativa aplicable.","la creación de un registro europeo de profesionales que ejerzan actividades por cuenta propia."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la coordinación de las disposiciones legales, reglamentarias y administrativas de los Estados miembros relativas al acceso a las actividades por cuenta propia y a su ejercicio</mark></span>El <span class=\"ref-norma\">art. 53.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"así como para la coordinación de las disposiciones\"</span>. Reconocimiento mutuo de títulos y coordinación de las disposiciones sobre acceso y ejercicio de actividades por cuenta propia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3346","p":"Tratado de Funcionamiento de la Unión Europea. Inmigración. El Parlamento Europeo y el Consejo podrán establecer, con arreglo al procedimiento legislativo ordinario, medidas para fomentar y apoyar la acción de los Estados miembros destinada a propiciar la integración de los nacionales de terceros países que residan legalmente en su territorio, con exclusión de:","o":["toda coordinación de las políticas de integración de los Estados miembros, salvo que se disponga otra cosa en la normativa aplicable.","toda financiación con cargo al presupuesto de la Unión.","toda cooperación con las autoridades locales y regionales.","toda armonización de las disposiciones legales y reglamentarias de los Estados miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">toda armonización de las disposiciones legales y reglamentarias de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 79.4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con exclusión de toda armonización de las disposiciones legales y reglamentarias de los Estados miembros\"</span>. Se excluye la armonización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3349","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia civil. La Unión desarrollará una cooperación judicial en asuntos civiles con repercusión transfronteriza, basada en el principio de reconocimiento mutuo de las resoluciones judiciales y extrajudiciales; esta cooperación podrá incluir:","o":["la adopción de medidas de aproximación de las disposiciones legales y reglamentarias de los Estados miembros.","la creación de tribunales especializados con competencia en asuntos civiles transfronterizos, en los términos que establezca la propia norma.","la armonización de los procedimientos civiles de los Estados miembros mediante reglamentos.","la adopción de un código civil europeo de aplicación directa en los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">la adopción de medidas de aproximación de las disposiciones legales y reglamentarias de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 81.1 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Esta cooperación podrá incluir la adopción de medidas de aproximación de las disposiciones legales y\"</span>. Puede incluir medidas de aproximación de las disposiciones legales y reglamentarias. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3415","p":"Tratado de Funcionamiento de la Unión Europea. Cooperación judicial en materia penal. El Parlamento Europeo y el Consejo podrán establecer, con arreglo al procedimiento legislativo ordinario, medidas que impulsen y apoyen la actuación de los Estados miembros en el ámbito de la prevención de la delincuencia, con exclusión de:","o":["toda financiación con cargo al presupuesto de la Unión.","toda coordinación de las autoridades policiales de los Estados miembros, conforme al procedimiento que se establezca reglamentariamente.","toda armonización de las disposiciones legales y reglamentarias de los Estados miembros.","toda cooperación con terceros países."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">toda armonización de las disposiciones legales y reglamentarias de los Estados miembros</mark></span>El <span class=\"ref-norma\">art. 84 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"con exclusión de toda armonización de las disposiciones legales y reglamentarias de los Esta-dos miembros\"</span>. Prevención de la delincuencia: apoyo, sin armonización. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículos 229 a 234 TFUE — Funcionamiento del PE y moción de censura ✱ R22","q":[{"i":"3-71","p":"Tratado de Funcionamiento de la Unión Europea. El Defensor del Pueblo presentará al Parlamento Europeo un informe sobre el resultado de sus investigaciones:","o":["Cada año.","Cada semestre.","Cada dos años.","Cada tres meses."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Cada año</mark></span>El <span class=\"ref-norma\">art. 228.1 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones\"</span>. El artículo 228.1 del TFUE dispone que el Defensor del Pueblo presentará cada año al Parlamento Europeo un informe sobre el resultado de sus investigaciones."},{"i":"3-280","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo se reunirá sin necesidad de previa convocatoria:","o":["El primer miércoles de marzo.","El segundo martes de marzo.","El segundo miércoles de marzo.","El primer martes de marzo."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El segundo martes de marzo</mark></span>El <span class=\"ref-norma\">art. 229 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo celebrará cada año un período de sesiones. Se reunirá sin necesidad de previa convocatoria el segundo martes de marzo. El Parlamento Europeo podrá reunirse en período parcial de sesiones extraordinario a petición de\"</span>. Según el art. 229 TFUE, el Parlamento Europeo se reunirá sin necesidad de previa convocatoria el segundo martes de marzo."},{"i":"3-ia-3444","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo celebrará cada año un período de sesiones y se reunirá sin necesidad de previa convocatoria:","o":["el primer martes de marzo.","el segundo martes de marzo.","el segundo martes de septiembre.","el primer lunes de octubre."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">el segundo martes de marzo</mark></span>El <span class=\"ref-norma\">art. 229 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Se reunirá sin necesidad de previa convocatoria el segundo martes de marzo\"</span>. El segundo martes de marzo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-134","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones Institucionales. El Parlamento Europeo podrá reunirse en período parcial de sesiones extraordinario a petición de:","o":["La mayoría de los miembros que lo componen.","Del Consejo.","De la Comisión.","Todas son correctas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son correctas</mark></span>El <span class=\"ref-norma\">art. 229 del TFUE</span> dispone: <span class=\"ref-concepto\">\"la mayoría de los miembros que lo componen, del Consejo o de la Comisión\"</span>. El artículo 229 del TFUE establece que el Parlamento Europeo podrá reunirse en período parcial de sesiones extraordinario a petición de la mayoría de los miembros que lo componen, del Consejo o de la Comisión."},{"i":"3-156","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales y financieras. El Parlamento Europeo. El Parlamento Europeo podrá reunirse en período parcial de sesiones extraordinario a petición de: Señale la INCORRECTA.","o":["De la Comisión.","La mayoría cualificada de los miembros que lo componen.","Del Consejo.","La mayoría de los miembros que lo componen."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">La mayoría cualificada de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 229 del TFUE</span> dispone: <span class=\"ref-concepto\">\"la mayoría de los miembros que lo componen, del Consejo o de la Comisión\"</span>. La opción correcta es la B, por ser la incorrecta. El artículo 229 del TFUE exige la petición de la mayoría de los miembros que componen el Parlamento Europeo, del Consejo o de la Comisión para convocar un período parcial de sesiones extraordinario, sin que se prevea una mayoría cualificada para ello."},{"i":"3-285","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo podrá reunirse en periodo parcial de sesiones extraordinario a petición de: señale la INCORRECTA.","o":["El Consejo.","La mayoría de los miembros que lo componen.","La Comisión.","La cuarta parte de sus miembros."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">La cuarta parte de sus miembros</mark></span>La cuarta parte de los miembros es el requisito de la comisión temporal de investigación (art. 226). Según el <span class=\"ref-norma\">art. 229 del TFUE</span>: <span class=\"ref-concepto\">\"El Parlamento Europeo podrá reunirse en período parcial de sesiones extraordinario a petición de: la mayoría de los miembros que lo componen, del Consejo o de la Comisión.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3501","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo podrá reunirse en período parcial de sesiones extraordinario a petición de la mayoría de los miembros que lo componen, del Consejo o:","o":["de la Comisión.","del Consejo Europeo.","del Presidente del Parlamento Europeo exclusivamente.","de un tercio de los Estados miembros."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">de la Comisión</mark></span>El <span class=\"ref-norma\">art. 229 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"la mayoría de los miembros que lo componen, del Consejo o de la Comisión\"</span>. Pueden pedirlo la mayoría de sus miembros, el Consejo o la Comisión. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-246","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo. Salvo disposición en contrario de los Tratados, ¿cómo decidirá el Parlamento Europeo?","o":["Por mayoría cualificada.","Por consenso.","Por mayoría de los votos emitidos.","Por unanimidad de los votos emitidos."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Por mayoría de los votos emitidos</mark></span>El <span class=\"ref-norma\">art. 231 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Salvo disposición en contrario de los Tratados, el Parlamento Europeo decidirá por mayoría de los votos emitidos. El reglamento interno fijará el quórum\"</span>. El artículo 231 del TFUE establece que, salvo disposición en contrario de los Tratados, el Parlamento Europeo decidirá por mayoría de los votos emitidos."},{"i":"3-128","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo establecerá su propio reglamento interno por:","o":["Mayoría de los miembros que lo componen.","Mayoría de dos tercios de los miembros que lo componen.","Mayoría absoluta de los miembros que lo componen.","Todas son incorrectas."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mayoría de los miembros que lo componen</mark></span>Se marca la fórmula literal del Tratado. Según el <span class=\"ref-norma\">art. 232 del TFUE</span>: <span class=\"ref-concepto\">\"El Parlamento Europeo establecerá su propio reglamento interno por mayoría de los miembros que lo componen.\"</span> (verificado con el texto del temario)."},{"i":"3-150","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo establecerá su propio reglamento interno por ______ de los miembros que lo componen.","o":["Mayoría.","Mayoría de dos tercios.","Mayoría cualificada.","Mayoría absoluta."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Mayoría</mark></span>Se marca la fórmula literal del Tratado («mayoría»). Según el <span class=\"ref-norma\">art. 232 del TFUE</span>: <span class=\"ref-concepto\">\"El Parlamento Europeo establecerá su propio reglamento interno por mayoría de los miembros que lo componen.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3504","p":"Tratado de Funcionamiento de la Unión Europea. Parlamento Europeo. El Parlamento Europeo establecerá su propio reglamento interno:","o":["por mayoría de los votos emitidos.","por mayoría de los miembros que lo componen.","por mayoría de dos tercios de los miembros, sin perjuicio de lo dispuesto en otras disposiciones.","por unanimidad de los grupos políticos."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">por mayoría de los miembros que lo componen</mark></span>El <span class=\"ref-norma\">art. 232 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo establecerá su propio reglamento interno por mayoría de los miembros que lo componen\"</span>. Mayoría de los miembros que lo componen (no de los votos emitidos). <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-132","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones Institucionales. El Parlamento Europeo procederá a la discusión, en sesión pública, ________, que le presentará la Comisión.","o":["Del informe general semestral.","Del informe general mensual.","Del informe general anual.","Todas son incorrectas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Del informe general anual</mark></span>El <span class=\"ref-norma\">art. 233 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo procederá a la discusión, en sesión pública, del informe general anual que le presentará la Comisión\"</span>. El artículo 233 del TFUE establece que el Parlamento Europeo procederá a la discusión, en sesión pública, del informe general anual que le presentará la Comisión."},{"i":"3-153","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo procederá a la discusión, en sesión pública, del ______ que le presentará la Comisión.","o":["Informe semestral.","Informe periódico.","Informe general anual.","Informe trimestral."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Informe general anual</mark></span>El <span class=\"ref-norma\">art. 233 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Parlamento Europeo procederá a la discusión, en sesión pública, del informe general anual que le presentará la Comisión\"</span>. El artículo 233 del TFUE establece que el Parlamento Europeo procederá a la discusión, en sesión pública, del informe general anual que le presentará la Comisión."},{"i":"3-72","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo, en caso de que se le someta una moción de censura sobre la gestión de la Comisión, solo podrá pronunciarse sobre dicha moción transcurridos:","o":["Cinco días como mínimo desde la fecha de su presentación y en votación pública.","Diez días como mínimo desde la fecha de su presentación y en votación pública.","Tres días como mínimo desde la fecha de su presentación y en votación pública.","Doce días como mínimo desde la fecha de su presentación y en votación pública."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tres días como mínimo desde la fecha de su presentación y en votación pública</mark></span>El <span class=\"ref-norma\">art. 234 del TFUE</span> dispone: <span class=\"ref-concepto\">\"sólo podrá pronunciarse sobre dicha moción transcurridos tres días como mínimo desde la fecha de su presentación y en votación pública\"</span>. El artículo 234 del TFUE establece que el Parlamento Europeo, en caso de que se le someta una moción de censura sobre la gestión de la Comisión, sólo podrá pronunciarse transcurridos tres días como mínimo desde la fecha de su presentación y en votación pública."},{"i":"3-311","p":"Tratado de Funcionamiento de la Unión Europea. El Parlamento Europeo, en caso de que se le someta una moción de censura sobre la gestión de la Comisión, solo podrá pronunciarse sobre dicha moción transcurridos:","o":["Cinco días como mínimo desde la fecha de su presentación y en votación pública.","Diez días como mínimo desde la fecha de su presentación y en votación pública.","Tres días como mínimo desde la fecha de su presentación y en votación pública.","Doce días como mínimo desde la fecha de su presentación y en votación pública."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Tres días como mínimo desde la fecha de su presentación y en votación pública</mark></span>El <span class=\"ref-norma\">art. 234 del TFUE</span> dispone: <span class=\"ref-concepto\">\"sólo podrá pronunciarse sobre dicha moción transcurridos tres días como mínimo desde la fecha de su presentación y en votación pública\"</span>. El artículo 234 TFUE exige que transcurran al menos tres días desde la presentación de la moción de censura."},{"i":"3-ia-3506","p":"Tratado de Funcionamiento de la Unión Europea. Moción de censura. El Parlamento Europeo, en caso de que se le someta una moción de censura sobre la gestión de la Comisión, sólo podrá pronunciarse sobre dicha moción transcurridos como mínimo:","o":["siete días desde la fecha de su presentación y en votación secreta.","veinticuatro horas desde la fecha de su presentación y en votación pública.","quince días desde la fecha de su presentación y en votación pública.","tres días desde la fecha de su presentación y en votación pública."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">tres días desde la fecha de su presentación y en votación pública</mark></span>El <span class=\"ref-norma\">art. 234 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"transcurridos tres días como mínimo desde la fecha de su presentación y en votación pública\"</span>. Tres días y votación pública. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-44","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales y financieras. En materia de una moción de censura sobre la gestión de la Comisión, señale la opción correcta:","o":["Deberá ser aprobada por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo.","Deberá ser aprobada por mayoría de un cuarto de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo.","Deberá ser aprobada por mayoría de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo.","Deberá ser aprobada por mayoría de los votos emitidos que representen, a su vez, la mayoría de dos tercios de los diputados que componen el Parlamento Europeo."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Deberá ser aprobada por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 234 del TFUE</span> dispone: <span class=\"ref-concepto\">\"Si la moción de censura es aprobada por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo, los miembros de la Comisión deberán dimitir colectivamente de sus cargos\"</span>. El artículo 234 del TFUE exige que la moción de censura sea aprobada por mayoría de dos tercios de los votos emitidos, que representen a su vez la mayoría de los diputados que componen el Parlamento Europeo."},{"i":"3-161","p":"Tratado de la Unión Europea. El Consejo Europeo nombrará por ______ con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad.","o":["Mayoría simple.","Mayoría absoluta.","Mayoría de dos tercios.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span>El <span class=\"ref-norma\">art. 18.1 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El Consejo Europeo nombrará por mayoría cualificada, con la aprobación del Presidente de la Comisión, al Alto Representante de la Unión para Asuntos Exteriores y Política de Seguridad. El Consejo Europeo podrá poner fin a su mandato por el mismo procedimiento\"</span>. El artículo 18.1 del TUE establece que el Consejo Europeo nombrará al Alto Representante por mayoría cualificada, con la aprobación del Presidente de la Comisión, mayoría que no coincide con ninguna de las opciones numéricas erróneas ofrecidas (simple, absoluta o dos tercios)."},{"i":"3-ia-3507","p":"Tratado de Funcionamiento de la Unión Europea. Moción de censura. La moción de censura contra la Comisión se aprobará por mayoría de dos tercios de los votos emitidos que representen, a su vez:","o":["los dos tercios de los diputados que componen el Parlamento Europeo.","la mayoría de los Estados miembros representados en el Parlamento.","la mayoría de los diputados que componen el Parlamento Europeo.","la mayoría absoluta de los grupos políticos del Parlamento Europeo."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la mayoría de los diputados que componen el Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 234 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Si la moción de censura es aprobada por mayoría de dos tercios de los votos emitidos que representen, a su vez, la mayoría de los diputados que componen el Parlamento Europeo\"</span>. Dos tercios de los votos emitidos que sean, a su vez, mayoría de los diputados. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3508","p":"Tratado de Funcionamiento de la Unión Europea. Moción de censura. Aprobada la moción de censura, los miembros de la Comisión deberán dimitir colectivamente y permanecerán en sus cargos y continuarán despachando los asuntos de administración ordinaria hasta que sean sustituidos; el mandato de los miembros designados para sustituirlos:","o":["será de cinco años desde su nombramiento.","expirará en la fecha en que habría expirado el mandato de los miembros obligados a dimitir.","será de dos años y medio renovable.","expirará con las siguientes elecciones al Parlamento Europeo, sin perjuicio de lo dispuesto en otras disposiciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">expirará en la fecha en que habría expirado el mandato de los miembros obligados a dimitir</mark></span>El <span class=\"ref-norma\">art. 234 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el mandato de los miembros de la Comisión designados para sustituirlos expirará en la fecha en que habría expirado el mandato\"</span>. El mandato de los sustitutos expira cuando habría expirado el de los dimitidos. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]},{"a":"Artículo 300 TFUE — CES y Comité de las Regiones","q":[{"i":"3-275","p":"(TFUE) - Tratado de la Unión Europea. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones:","o":["Decisorias.","Consultivas.","Organizativas.","Administrativas."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Consultivas</mark></span>El <span class=\"ref-norma\">art. 13.4 del TUE</span> dispone: <span class=\"ref-concepto\">\"El PARLAMENTO EUROPEO, el CONSEJO y la COMISIÓN estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones que ejercerán funciones consultivas\"</span>. El artículo 300.1 del TFUE establece que el Comité Económico y Social y el Comité de las Regiones ejercerán funciones consultivas."},{"i":"3-69","p":"Tratado de Funcionamiento de la Unión Europea. Órganos consultivos de la Unión. En relación al Comité Económico y Social, señale la correcta:","o":["Estará compuesto por representantes de las organizaciones de empresarios, de los trabajadores y de otros sectores representativos de la sociedad civil, en particular en los ámbitos económico, cívico, social y cultural.","Estará compuesto por representantes de las organizaciones de económicos y de otros sectores representativos de la sociedad civil, en particular en los ámbitos socioeconómicos, cívico, profesional y cultural.","Estará compuesto por representantes de los entes regionales y locales que sean titulares de un mandato electoral en un ente regional o local.","Todas son incorrectas."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">Todas son incorrectas</mark></span>A cambia los ámbitos («económico, cívico, social») y B los deforma; C describe al Comité de las Regiones (art. 300.3). Según el <span class=\"ref-norma\">art. 300.2 del TFUE</span>: <span class=\"ref-concepto\">\"El Comité Económico y Social estará compuesto por representantes de las organizaciones de empresarios, de trabajadores y de otros sectores representativos de la sociedad civil, en particular en los ámbitos socioeconómico, cívico, profesional y cultural.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3042","p":"Tratado de la Unión Europea. Participación ciudadana. Las instituciones darán a los ciudadanos y a las asociaciones representativas, por los cauces apropiados, la posibilidad de expresar e intercambiar públicamente sus opiniones en todos los ámbitos de actuación de la Unión; además, mantendrán un diálogo abierto, transparente y regular con:","o":["las asociaciones representativas y los interlocutores sociales.","los ciudadanos y los Parlamentos nacionales.","las organizaciones no gubernamentales y los ciudadanos.","las asociaciones representativas y la sociedad civil."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">las asociaciones representativas y la sociedad civil</mark></span>El <span class=\"ref-norma\">art. 11.1 y 2 de el Tratado de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Las instituciones mantendrán un diálogo abierto, transparente y regular con las asociaciones repre\"</span>. El diálogo es abierto, transparente y regular con las asociaciones representativas y la sociedad civil. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3639","p":"Tratado de Funcionamiento de la Unión Europea. Órganos consultivos. El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Económico y Social y por un Comité de las Regiones, que ejercerán funciones consultivas; el Comité Económico y Social estará compuesto por representantes de las organizaciones de empresarios, de trabajadores y de otros sectores representativos de:","o":["la sociedad civil, en particular en los ámbitos económico, social, territorial y medioambiental.","los Estados miembros, en particular en los ámbitos económico, laboral, profesional y cultural.","la sociedad civil, en particular en los ámbitos socioeconómico, cívico, profesional y cultural.","las asociaciones representativas, en particular en los ámbitos económico, cívico, sindical y cultural."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">la sociedad civil, en particular en los ámbitos socioeconómico, cívico, profesional y cultural</mark></span>El <span class=\"ref-norma\">art. 300.1 y 2 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"de otros sectores representativos de la sociedad civil, en particular en los ámbitos socioeconómico, cívico, profesional y cultural\"</span>. Empresarios, trabajadores y otros sectores de la sociedad civil: ámbitos socioeconómico, cívico, profesional y cultural. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-149","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales y financieras. Órganos consultivos de la Unión. Señale la correcta.","o":["El Comité Económico y Social estará compuesto por representantes de los entes regionales y locales que sean titulares de un mandato electoral en un ente regional o local.","El Comité de las Regiones estará compuesto por representantes de las organizaciones de empresarios, de trabajadores y de otros sectores representativos de la sociedad civil.","Los miembros del Comité Económico y Social y del Comité de las Regiones no estarán vinculados por ningún mandato imperativo.","El Parlamento Europeo, el Consejo y la Comisión estarán asistidos por un Comité Ético y Moral y por un Comité de las Regiones."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Los miembros del Comité Económico y Social y del Comité de las Regiones no estarán vinculados por ningún mandato imperativo</mark></span>El <span class=\"ref-norma\">art. 300.4 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los miembros del Comité Económico y Social y del Comité de las Regiones no estarán vinculados por ningún mandato imperativo. Ejercerán sus funciones con plena independencia, en interés general de la Unión\"</span>. El artículo 300 del TFUE regula el Comité Económico y Social (compuesto por representantes de organizaciones de empresarios, trabajadores y sociedad civil) y el Comité de las Regiones (compuesto por representantes de entes regionales y locales con mandato electoral), estableciendo que sus miembros no estarán vinculados por mandato imperativo alguno."},{"i":"3-ia-3640","p":"Tratado de Funcionamiento de la Unión Europea. Órganos consultivos. El Comité de las Regiones estará compuesto por representantes de los entes regionales y locales que sean titulares de un mandato electoral en un ente regional o local, o que tengan responsabilidad política ante una asamblea elegida; los miembros de ambos Comités:","o":["estarán vinculados por las instrucciones de sus gobiernos y ejercerán sus funciones en interés de los Estados miembros, sin perjuicio de lo dispuesto en otras disposiciones.","no estarán vinculados por ningún mandato imperativo y ejercerán sus funciones con plena independencia, en interés general de la Unión.","no estarán vinculados por ningún mandato imperativo, pero deberán rendir cuentas ante su ente de origen.","ejercerán sus funciones con independencia, aunque podrán recibir instrucciones de las instituciones."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">no estarán vinculados por ningún mandato imperativo y ejercerán sus funciones con plena independencia, en interés general de la Unión</mark></span>El <span class=\"ref-norma\">art. 300.3 y 4 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"no estarán vinculados por ningún mandato imperativo. Ejercerán sus funciones con plena independencia, en interés general de la Unión\"</span>. Sin mandato imperativo y con plena independencia. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-1","p":"Tratado de Funcionamiento de la Unión Europea. Órganos consultivos de la Unión. Los miembros del Comité Económico y Social y del Comité de las Regiones:","o":["Estarán vinculados por mandato imperativo.","Ejercerán sus funciones con dependencia al Parlamento Europeo, el Consejo y la Comisión.","Ejercerán sus funciones en interés general de la Unión.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ejercerán sus funciones en interés general de la Unión</mark></span>El <span class=\"ref-norma\">art. 300.4 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los miembros del Comité Económico y Social y del Comité de las Regiones no estarán vinculados por ningún mandato imperativo. Ejercerán sus funciones con plena independencia, en interés general de la Unión\"</span>. El artículo 300.4 del TFUE establece que los miembros del Comité Económico y Social y del Comité de las Regiones no estarán vinculados por ningún mandato imperativo y ejercerán sus funciones con plena independencia, en interés general de la Unión, por lo que quedan descartadas la A y la B."},{"i":"3-315","p":"Tratado de Funcionamiento de la Unión Europea. Órganos Consultivos de la Unión. Los miembros del Comité Económico y Social y del Comité de las Regiones:","o":["Estarán vinculados por mandato imperativo.","Ejercerán sus funciones con dependencia al Parlamento Europeo, el Consejo y la Comisión.","Ejercerán sus funciones en interés general de la Unión.","Todas son correctas."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Ejercerán sus funciones en interés general de la Unión</mark></span>El <span class=\"ref-norma\">art. 300.4 del TFUE</span> dispone: <span class=\"ref-concepto\">\"\u0007Los miembros del Comité Económico y Social y del Comité de las Regiones no estarán vinculados por ningún mandato imperativo. Ejercerán sus funciones con plena independencia, en interés general de la Unión\"</span>. El artículo 300.4 TFUE dispone que los miembros de ambos Comités no estarán vinculados por mandato imperativo alguno y ejercerán sus funciones con plena independencia, en interés general de la Unión."}]},{"a":"Artículos 305 a 307 TFUE — Comité de las Regiones ✱ R29","q":[{"i":"3-133","p":"Tratado de Funcionamiento de la Unión Europea. El Comité de las Regiones. El número de miembros del Comité de las Regiones no excederá de:","o":["Trescientos cincuenta.","Cuatrocientos.","Cuatrocientos cincuenta.","Quinientos."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">Trescientos cincuenta</mark></span>El <span class=\"ref-norma\">art. 301 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El número de miembros del Comité Económico y Social no excederá de trescientos cincuenta. El Consejo adoptará por unanimidad, a propuesta de la Comisión, una decisión por la que se establezca la composición del Comité. El Consejo establecerá las dietas de los miembros del Comité\"</span>. Según el art. 305 TFUE, el número de miembros del Comité de las Regiones no excederá de trescientos cincuenta."},{"i":"3-12","p":"Tratado de la Unión Europea. Disposiciones sobre las instituciones. El mandato de la Comisión será de:","o":["Cuatro años.","Tres años.","Cinco años.","Ocho años."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Cinco años</mark></span>El <span class=\"ref-norma\">art. 17.3 del TUE</span> dispone: <span class=\"ref-concepto\">\"\u0007El mandato de la Comisión será de cinco años\"</span>. El artículo 17.3 del TUE establece que el mandato de la Comisión será de cinco años."},{"i":"3-ia-3538","p":"Tratado de Funcionamiento de la Unión Europea. Tribunal de Justicia. Los jueces elegirán de entre ellos al Presidente del Tribunal de Justicia por un período de tres años, y su mandato será:","o":["no renovable.","renovable una sola vez.","de dos años y medio.","renovable."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">renovable</mark></span>El <span class=\"ref-norma\">art. 253 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Los jueces elegirán de entre ellos al Presidente del Tribunal de Justicia por un período de tres años. Su mandato será renovable\"</span>. Tres años, renovable. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-34","p":"Tratado de Funcionamiento de la Unión Europea. ¿Quién designará a los miembros del Comité de las Regiones?","o":["El Parlamento Europeo.","El Consejo, que adoptará la lista de miembros y suplentes establecida de conformidad con las propuestas presentadas por cada Estado miembro.","El Consejo, por unanimidad, a propuesta del Estado miembro.","La Comisión, por mayoría cualificada, a propuesta del Estado miembro."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">El Consejo, que adoptará la lista de miembros y suplentes establecida de conformidad con las propuestas presentadas por cada Estado miembro</mark></span>Ojo: la unanimidad (a propuesta de la Comisión) es para la decisión sobre la COMPOSICIÓN del Comité, no para adoptar la lista de miembros. Según el <span class=\"ref-norma\">art. 305 del TFUE</span>: <span class=\"ref-concepto\">\"Los miembros del Comité, así como un número igual de suplentes, serán nombrados para un período de cinco años. Su mandato será renovable. El Consejo adoptará la lista de miembros y suplentes establecida de conformidad con las propuestas presentadas por cada Estado miembro.\"</span> (verificado con el texto del temario)."},{"i":"3-ia-3529","p":"Tratado de Funcionamiento de la Unión Europea. Comisión. El Consejo, por unanimidad y a propuesta del Presidente de la Comisión, podrá decidir que no ha lugar a la sustitución de un miembro dimisionario, cesado o fallecido, en particular:","o":["cuando quede poco tiempo para que termine el mandato de dicho miembro.","cuando el Estado miembro afectado no proponga candidato en el plazo de un mes.","cuando el miembro haya sido cesado por falta grave.","cuando el número de miembros sea superior a los dos tercios de los Estados."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">cuando quede poco tiempo para que termine el mandato de dicho miembro</mark></span>El <span class=\"ref-norma\">art. 246 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"en particular cuando quede poco tiempo para que termine el mandato de dicho miembro\"</span>. Unanimidad, a propuesta del Presidente, cuando quede poco para el fin del mandato. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3649","p":"Tratado de Funcionamiento de la Unión Europea. Comité de las Regiones. Los miembros del Comité de las Regiones y sus suplentes son nombrados por cinco años; al término del mandato electoral regional o local en virtud del cual hayan sido propuestos, el mandato de los miembros del Comité:","o":["concluirá automáticamente y serán sustituidos para el período restante según el mismo procedimiento.","se prorrogará hasta que el Consejo nombre a sus sustitutos, en los términos que establezca la propia norma.","se mantendrá hasta el final del período de cinco años.","concluirá una vez que el Consejo acepte su dimisión."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">concluirá automáticamente y serán sustituidos para el período restante según el mismo procedimiento</mark></span>El <span class=\"ref-norma\">art. 305 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"el mandato de los miembros del Comité concluirá automáticamente y serán sustituidos para el período restante\"</span>. El mandato termina automáticamente al perder el mandato electoral regional o local. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3648","p":"Tratado de Funcionamiento de la Unión Europea. Comité de las Regiones. El número de miembros del Comité de las Regiones no excederá de trescientos cincuenta; los miembros, así como un número igual de suplentes, serán nombrados para un período de cinco años, y su mandato será renovable; además, ningún miembro del Comité podrá ser simultáneamente:","o":["miembro del Comité Económico y Social.","miembro del Parlamento Europeo.","miembro de un Gobierno de un Estado miembro.","miembro de una asamblea regional."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">miembro del Parlamento Europeo</mark></span>El <span class=\"ref-norma\">art. 305 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Ningún miembro del Comité podrá ser simultáneamente miembro del Parlamento Europeo\"</span>. Incompatibilidad con ser miembro del Parlamento Europeo. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3653","p":"Tratado de Funcionamiento de la Unión Europea. Comité de las Regiones. El dictamen del Comité de las Regiones será remitido, junto con el acta de las deliberaciones:","o":["al Parlamento Europeo, al Consejo y a la Comisión.","al Parlamento Europeo y al Consejo Europeo.","al Consejo y a la Comisión exclusivamente.","a las instituciones y a los Estados miembros, en los términos que establezca la propia norma."],"c":0,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>A</b> · <mark class=\"ex-key\">al Parlamento Europeo, al Consejo y a la Comisión</mark></span>El <span class=\"ref-norma\">art. 307 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"El dictamen del Comité será remitido al Parlamento Europeo, al Consejo y a la Comisión, junto con el acta\"</span>. Se remite a las tres instituciones junto con el acta de las deliberaciones. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-131","p":"Tratado de Funcionamiento de la Unión Europea. El Comité de las Regiones. El Comité de las Regiones designará de entre sus miembros al Presidente y a la Mesa, por un periodo de:","o":["Dos años.","Dos años y medio.","Tres años.","Un año y medio."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">Dos años y medio</mark></span>El <span class=\"ref-norma\">art. 306 del TFUE</span> dispone: <span class=\"ref-concepto\">\"El Comité de las Regiones designará de entre sus miembros al Presidente y a la Mesa, por un período de dos años y medio. Establecerá su reglamento interno. El Comité será convocado por su Presidente, a instancia del Parlamento Europeo, del Consejo o de la Comisión. También podrá reunirse por propia iniciativa\"</span>. El artículo 306 del TFUE dispone que el Comité de las Regiones designará de entre sus miembros al Presidente y a la Mesa por un período de dos años y medio."},{"i":"3-391","p":"Tratado de Funcionamiento de la Unión Europea. Disposiciones institucionales. Órganos consultivos de la Unión. Cuando el Comité Económico y Social sea consultado, el Parlamento Europeo, el Consejo o la Comisión informarán al Comité de las Regiones, que podrá emitir un dictamen cuando estime que hay:","o":["Intereses económicos y sociales generales en juego.","Intereses nacionales y regionales en juego.","Intereses regionales específicos en juego.","Intereses transfronterizos en juego."],"c":2,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>C</b> · <mark class=\"ex-key\">Intereses regionales específicos en juego</mark></span>El <span class=\"ref-norma\">art. 307 del TFUE</span> dispone: <span class=\"ref-concepto\">\"cuando estime que hay intereses regionales específicos en juego\"</span>. Cuando hay intereses regionales específicos en juego."},{"i":"3-ia-3646","p":"Tratado de Funcionamiento de la Unión Europea. Comité Económico y Social. El Comité Económico y Social será consultado por el Parlamento Europeo, el Consejo o por la Comisión, en los casos previstos en los Tratados; estas instituciones podrán consultarle en todos aquellos casos en que lo consideren oportuno y el Comité:","o":["no podrá emitir dictámenes sin ser consultado previamente.","deberá emitir un dictamen sobre toda propuesta legislativa, salvo que se disponga otra cosa en la normativa aplicable.","solo podrá emitir dictámenes por mandato del Consejo.","podrá tomar la iniciativa de emitir un dictamen cuando lo juzgue oportuno."],"c":3,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>D</b> · <mark class=\"ex-key\">podrá tomar la iniciativa de emitir un dictamen cuando lo juzgue oportuno</mark></span>El <span class=\"ref-norma\">art. 304 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"Podrá tomar la iniciativa de emitir un dictamen cuando lo juzgue oportuno\"</span>. Puede emitir dictámenes de propia iniciativa. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"},{"i":"3-ia-3652","p":"Tratado de Funcionamiento de la Unión Europea. Comité de las Regiones. Cuando el Comité Económico y Social sea consultado, el Parlamento Europeo, el Consejo o la Comisión informarán al Comité de las Regiones de esta solicitud de dictamen, y el Comité de las Regiones podrá emitir un dictamen al respecto:","o":["cuando lo solicite el Comité Económico y Social.","cuando estime que hay intereses regionales específicos en juego.","cuando lo autorice la institución que haya consultado al Comité Económico y Social.","cuando afecte a la cooperación transfronteriza."],"c":1,"e":"<span class=\"ex-resp\">Respuesta correcta: <b>B</b> · <mark class=\"ex-key\">cuando estime que hay intereses regionales específicos en juego</mark></span>El <span class=\"ref-norma\">art. 307 de el Tratado de Funcionamiento de la Unión Europea</span> dispone: <span class=\"ref-concepto\">\"podrá emitir un dictamen al respecto cuando estime que hay intereses regionales específicos en juego\"</span>. Puede dictaminar cuando haya intereses regionales específicos en juego. <em style=\"color:var(--texto-gris)\">(Pregunta generada por IA)</em>"}]}];
